 = (qv.count(\"a\") rescue $!.class); p r\n\n      t = Thread.new { \"aabbcc\" }\n      tv = t.value\n      r = (tv.partition(\"b\") rescue $!.class); p r\n      r = (tv.sum rescue $!.class); p r\n\n      # A boxed Array answers the names it shares with String on its own terms: the\n      # String arms must never claim a receiver whose runtime class is unknown.\n      a = fv([1, 2, 2, 3])\n      p a.count(2)\n      p a.index(2)\n      p a.rindex(2)\n      p a.sum\n      p a.slice(1, 2)\n      p a.insert(1, 9)\n      p a\n      p fv({ \"a\" => 1, \"b\" => 2 }).count\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      \"abc\"\n      2\n      3\n      2\n      [\"aa\", \"b\", \"bcc\"]\n      [\"aab\", \"b\", \"cc\"]\n      \"ab\"\n      11189196\n      0\n      \"xcc\"\n      0\n      true\n      \"abFZSxKKdq5s6\"\n      \"aXabbcc\"\n      \"aXabbcc\"\n      \"abc\"\n      \"abc\"\n      nil\n      \"abc\"\n      \"pad\"\n      \"PAD\"\n      \"PAD\"\n      2\n      588\n      76\n      \"v=5\"\n      \"v=5\"\n      \"aabbcc\"\n      \"a\"\n      \"ab\"\n      6\n      97\n      \"bbcc\"\n      \"AABBCC\"\n      [\"aa\", \"\", \"cc\"]\n      \"xbbcc\"\n      \"aayycc\"\n      \"zzbbcc\"\n      \"abc\"\n      \"bbcc\"\n      \"aabb\"\n      [\"a\", \"a\", \"b\", \"b\", \"c\", \"c\"]\n      [97, 97, 98, 98, 99, 99]\n      true\n      true\n      \"ccbbaa\"\n      \"--aabbcc--\"\n      :aabbcc\n      [\"a\", \"a\", \"b\", \"b\", \"c\", \"c\"]\n      588\n      2\n      2\n      [\"aa\", \"b\", \"bcc\"]\n      588\n      2\n      1\n      2\n      8\n      [2, 2]\n      [1, 9, 2, 2, 3]\n      [1, 9, 2, 2, 3]\n      2\n    OUT\n  end\n\n  it \"poly time surface\" do\n    result = ze0(<<~'RUBY')\n      # A Time that arrives boxed -- read out of a container, or narrowed out of an\n      # untyped value by is_a?(Time) -- reached a poly surface that had only the\n      # scalar accessors on it. Everything that answers a Time, a boolean, an offset,\n      # or a formatted str