(<<~'RUBY')\n      # The `TracePoint` rows that read nothing off the frame: the reentry guard,\n      # the per-VM statistics, and the four accessors a `:line` event refuses in\n      # CRuby too.\n\n      # Outside a handler there is nothing to re-enter.\n      begin\n        TracePoint.allow_reentry { 1 }\n      rescue RuntimeError => e\n        puts \"allow_reentry outside: \#{e.message}\"\n      end\n\n      puts \"stat: \#{TracePoint.stat.class}\"\n\n      seen = []\n      tp = TracePoint.new(:line) do |t|\n        %i[return_value parameters eval_script instruction_sequence].each do |m|\n          begin\n            t.public_send(m)\n            seen << \"\#{m}: answered\"\n          rescue RuntimeError => e\n            seen << \"\#{m}: \#{e.message}\"\n          end\n        end\n        t.disable\n      end\n\n      tp.enable\n      x = 1\n      tp.disable\n      puts seen.uniq.join(\"\\n\")\n\n      # Every accessor refuses from outside a handler first, whatever the event.\n      %i[return_value parameters self binding].each do |m|\n        TracePoint.new(:line) { }.public_send(m)\n      rescue RuntimeError => e\n        puts \"\#{m} outside: \#{e.message}\"\n      end\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      allow_reentry outside: No need to allow reentrance.\n      stat: Hash\n      return_value: not supported by this event\n      parameters: not supported by this event\n      eval_script: not supported by this event\n      instruction_sequence: not supported by this event\n      return_value outside: access from outside\n      parameters outside: access from outside\n      self outside: access from outside\n      binding outside: access from outside\n    OUT\n  end\nend\n", "../../spec/compiler/builtins/definition_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Builtins: defining and naming methods\" do\n  it \"arity errors attribute to the callee frame like cruby\" do\n    result = ze0(<<~'RUBY', path: \"compiler/builtins/arity_errors_attribute_to_the_callee_frame_like_cruby.rb\")\n      # CRuby raises wrong-number-of-arguments / missing-keyword INSIDE the\n      # callee: the innermost backtrace row is the callee's label at its\n      # `def` line, and an `initialize`-less `.new` shows the C-frame shape\n      # `'BasicObject#initialize'` at the CALLER's line. This battery was\n      # verified verbatim against ruby 4.0.6 (the arity family was previously\n      # an excluded, catalogued divergence of the frame-tracking battery).\n\n      def f(a, b)\n        a + b\n      end\n      begin\n        f(1)\n      rescue ArgumentError => e\n        puts e.message\n        puts e.backtrace.first.split('/').last\n      end\n      class Bag\n        def initialize(x)\n          @x = x\n        end\n      end\n      begin\n        Bag.new(1, 2, 3)\n      rescue ArgumentError => e\n        puts e.message\n        puts e.backtrace.first.split('/').last\n      end\n      class Plain; end\n      begin\n        Plain.new(5)\n      rescue ArgumentError => e\n        puts e.message\n        puts e.backtrace.first.split('/').last\n      end\n      def kw(x:)\n        x\n      end\n      begin\n        kw\n      rescue ArgumentError => e\n        puts e.message\n        puts e.backtrace.first.split('/').last\n      end\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      wrong number of arguments (given 1, expected 2)\n      arity_errors_attribute_to_the_callee_frame_like_cruby.rb:8:in 'Object#f'\n      wrong number of arguments (given 3, expected 1)\n      arity_errors_attribute_to_the_callee_frame_like_cruby.rb:18:in 'Bag#initialize'\n      wrong number of arguments (given 1, expected 0)\n      arity_errors_attribute_to_the_callee_frame_like_cruby.rb:30:in 'BasicObject#initialize'\n      missing keyword: :x\n      arity_errors_attribute_to_the_callee_frame_like_cruby.rb:35:in 'Object#kw'\n    OUT\n  end\n\n  it \"arity keyword argument errors\" do\n    result = ze0(<<~'RUBY')\n      # Statically-detectable argument-shape errors raise ArgumentError at runtime,\n      # in CRuby's words: too many positionals, an unknown keyword, and a missing\n      # required keyword. An options-hash call (no keyword matches any parameter)\n      # still collapses into the positional hash, and splat/rest shapes are exempt.\n      def m(a, b) = a + b\n      begin\n        puts m(1, 2, 3)\n      rescue ArgumentError => e\n        puts \"1: \#{e.message}\"\n      end\n      def k(a:) = a\n      begin\n        puts k(a: 1, zzz: 2)\n      rescue ArgumentError => e\n        puts \"2: \#{e.message}\"\n      end\n      class World\n        def initialize(width:, height:)\n          @w = width\n          @h = height\n        end\n        def area = @w * @h\n      end\n      begin\n        puts World.new(width: 150).area\n      rescue ArgumentError => e\n        puts \"3: \#{e.message}\"\n      end\n      puts World.new(width: 3, height: 4).area\n      def opts_hash(o = {}) = o.size\n      puts opts_hash(timeout: 5, retries: 2)\n      def rest(*xs) = xs.length\n      puts rest(1, 2, 3, 4)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      1: wrong number of arguments (given 3, expected 2)\n      2: unknown keyword: :zzz\n      3: missing keyword: :height\n      12\n      2\n      4\n    OUT\n  end\n\n  it \"builtin arity class methods\" do\n    result = ze0(<<~'RUBY')\n      # GAP -- imported from the spinel corpus at fa06b601.\n      #\n      # A builtin CLASS method's declared arity is wider than CRuby's, so a call\n      # CRuby rejects is accepted and the ArgumentError names the wrong range:\n      # zeo reports `expected 1..4` where CRuby says `1..3`.\n      #\n      # One row the arity census gated before it was retired at zero.\n      #\n      # The original header follows. It describes the PREDECESSOR project's\n      # version of this test and its own fix, not zeo's divergence above.\n      #\n      # A builtin class/module method called with a count CRuby rejects raises\n      # CRuby's ArgumentError. File.open with no arguments crashed the compiler.\n      def check\n        yield\n      rescue => e\n        p [e.class, e.message]\n      end\n\n      check { File.open }\n      check { File.new }\n      check { File.read }\n      check { File.write(\"only-a-path\") }\n      check { IO.for_fd }\n      check { IO.sysopen }\n      check { Time.at }\n      check { Hash.new(1, 2) }\n      check { Integer.sqrt }\n      check { Math.lgamma }\n      check { Dir.mkdir }\n      # the valid shapes still answer\n      p Hash.new(5)[:missing]\n      # A name no run ever creates: this corpus's own working directory is `tests/`,\n      # so anything plausible there is a file somebody may add.\n      p File.exist?(\"no-such-file-e7c1a0\")\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1..3)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1..3)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1..4)\"]\n      [ArgumentError, \"wrong number of arguments (given 1, expected 2..3)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1..2)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1..3)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1..3)\"]\n      [ArgumentError, \"wrong number of arguments (given 2, expected 0..1)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1..2)\"]\n      5\n      false\n    OUT\n  end\n\n  it \"builtin arity instance\" do\n    result = ze0(<<~'RUBY')\n      # A builtin instance method called with a count CRuby rejects raises\n      # CRuby's own ArgumentError, with its message.\n      #\n      # What this file was FILED for is fixed, and it was a PANIC:\n      # `Enumerable#first` with two arguments reached an `expect` in the body,\n      # and a panic cannot unwind out of `extern \"C\"`, so it ended the process.\n      # An `expect` is the wrong instrument for an argument the CALLER controls;\n      # ten of them in `builtins/enumerable.rs` are ordinary raises now.\n      #\n      # Two more rows were silently LENIENT rather than loud: `Array#first` read\n      # `args[0]` out of a `*args` it never counted, and `Range#first`/`#last`\n      # spelled their bound `0..1` where CRuby's message spells it `1`.\n\n      def check\n        yield\n      rescue => e\n        p [e.class, e.message]\n      end\n\n      # missing required argument (compile-time SIGSEGV before the arity guard)\n      check { (1..3).cover? }\n      check { (1..3).include? }\n      # an operator spelled as a method call with its operand missing\n      check { :a.<=> }\n      check { 1.+() }\n      # too few for an exact multi-argument method\n      s = +\"x\"\n      check { s.insert(1) }\n      h = {a: 1}\n      check { h.store(1) }\n      # too many for a zero-argument method\n      check { :a.to_s(9) }\n      check { \"x\".succ(1) }\n      # too many for a bounded optional range\n      check { \"x\".chomp(\"a\", \"b\") }\n      check { [1, 2].first(1, 2) }\n      check { (1..2).first(1, 2) }\n      # variadic minimum\n      a = [1]\n      check { a.insert }\n      # the valid shapes still answer\n      p (1..2).first\n      p \"x\".chomp\n      p [1, 2].first(1)\n      # a block changes several counts: the bare-call spec must not fire\n      p [1].fill { 9 }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1)\"]\n      [ArgumentError, \"wrong number of arguments (given 1, expected 2)\"]\n      [ArgumentError, \"wrong number of arguments (given 1, expected 2)\"]\n      [ArgumentError, \"wrong number of arguments (given 1, expected 0)\"]\n      [ArgumentError, \"wrong number of arguments (given 1, expected 0)\"]\n      [ArgumentError, \"wrong number of arguments (given 2, expected 0..1)\"]\n      [ArgumentError, \"wrong number of arguments (given 2, expected 0..1)\"]\n      [ArgumentError, \"wrong number of arguments (given 2, expected 1)\"]\n      [ArgumentError, \"wrong number of arguments (given 0, expected 1+)\"]\n      1\n      \"x\"\n      [1]\n      [9]\n    OUT\n  end\n\n  it \"builtin reopen methods reachable via send\" do\n    result = ze0(<<~'RUBY')\n      # `send` with a literal symbol reaches a reopen method through\n      # `send_value`'s value-method-first probe (the generated arity-checked\n      # trampoline), same result as the direct static call.\n\n      class String\n        def echo(a, b)\n          a.to_s + b.to_s + self\n        end\n      end\n\n      puts \"s\".send(:echo, 1, 2)\n      puts \"s\".echo(9, 8)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      12s\n      98s\n    OUT\n  end\n\n  it \"builtin reopen rest params and respond to\" do\n    result = ze0(<<~'RUBY')\n      # Full `Params` support on a reopen method (required + rest), plus\n      # `respond_to?` seeing value methods through the widened registry probe.\n\n      class String\n        def tag(first, *rest)\n          label = first.to_s\n          rest.each do |r|\n            label = label + \"|\" + r.to_s\n          end\n          label + \":\" + self\n        end\n      end\n\n      puts \"v\".tag(\"a\", \"b\", \"c\")\n      puts \"w\".tag(\"z\")\n      puts \"x\".respond_to?(:tag)\n      puts \"x\".respond_to?(:zzz)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      a|b|c:v\n      z:w\n      true\n      false\n    OUT\n  end\n\n  it \"class new arity\" do\n    result = ze0(<<~'RUBY')\n      # Class#new