de\"){ (\"a\"..\"e\").include?(\"bb\") }\n      t(\"cover\"){ (\"a\"..\"e\").cover?(\"bb\") }\n      t(\"step str\"){ (\"a\"..\"z\").step(5).to_a }\n      t(\"step sym\"){ (:a..:j).step(3).to_a }\n      t(\"each break\"){ (\"a\"..\"z\").step(2) { |s| break s } }\n      t(\"upto break\"){ \"a\".upto(\"z\") { |s| break s } }\n      t(\"range size\"){ (\"a\"..\"e\").size }\n      t(\"min/max\"){ [(\"a\"..\"e\").min, (\"a\"..\"e\").max] }\n      t(\"succ carry\"){ (\"az\"..\"bc\").to_a }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [\"str range\", [\"a\", \"b\", \"c\", \"d\", \"e\"]]\n      [\"str range x\", [\"a\", \"b\", \"c\", \"d\"]]\n      [\"str 2ch\", [\"aa\", \"ab\", \"ac\"]]\n      [\"str y-ab\", []]\n      [\"digits\", [\"9\", \"10\", \"11\"]]\n      [\"digits pad\", [\"08\", \"09\", \"10\", \"11\"]]\n      [\"digits x\", [\"9\", \"10\"]]\n      [\"sym\", [:a, :b, :c, :d, :e]]\n      [\"sym2\", [:aa, :ab, :ac]]\n      [\"upto\", [\"a\", \"b\", \"c\", \"d\", \"e\"]]\n      [\"upto excl\", [\"a\", \"b\", \"c\", \"d\"]]\n      [\"upto digits\", [\"9\", \"10\", \"11\"]]\n      [\"upto pad\", [\"08\", \"09\", \"10\"]]\n      [\"upto rev\", []]\n      [\"upto same\", [\"a\"]]\n      [\"upto ret\", \"a\"]\n      [\"include\", false]\n      [\"cover\", true]\n      [\"step str\", [\"a\", \"f\", \"k\", \"p\", \"u\", \"z\"]]\n      [\"step sym\", [:a, :d, :g, :j]]\n      [\"each break\", \"a\"]\n      [\"upto break\", \"a\"]\n      [\"range size\", nil]\n      [\"min/max\", [\"a\", \"e\"]]\n      [\"succ carry\", [\"az\", \"ba\", \"bb\", \"bc\"]]\n    OUT\n  end\nend\n", "../../spec/compiler/cache/cache_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Cache programs\" do\n  it \"const cache invalidation\" do\n    result = ze0(<<~'RUBY')\n      WHICH = \"first\"\n\n      def read_which = WHICH\n\n      # Warm the site, then reassign the same constant. Ruby warns and rebinds; the\n      # cached read must not survive the rebinding.\n      p read_which\n      Object.send(:remove_const, :WHICH)\n      WHICH = \"second\"\n      p read_which\n\n      module Shelf\n        ITEM = \"shelf\"\n        def self.item = ITEM\n      end\n      p Shelf.item\n      Shelf.send(:remove_const, :ITEM)\n      Shelf.const_set(:ITEM, \"restocked\")\n      p Shelf.item\n\n      # A constant read that MISSES caches nothing, so defining the name afterwards\n      # has to take effect.\n      def read_late = LATE\n      begin\n        read_late\n      rescue NameError => e\n        p e.message\n      end\n      LATE = 42\n      p read_late\n\n      # Removing a constant after the site has cached it must raise again.\n      def read_gone = GONE\n      GONE = 1\n      p read_gone\n      Object.send(:remove_const, :GONE)\n      begin\n        read_gone\n      rescue NameError => e\n        p e.message\n      end\n\n      # A nested class named only once it is bound to a constant becomes reachable\n      # through that namespace.\n      module Box; end\n      def read_inner = Box::Inner\n      begin\n        read_inner\n      rescue NameError => e\n        p e.class\n      end\n      Box.const_set(:Inner, Class.new)\n      p read_inner.name\n      p read_inner.name\n\n      # Threads share one constant table, so a value written by one is what the\n      # other's cached site must answer with.\n      SHARED = \"before\"\n      def read_shared = SHARED\n      p read_shared\n      Thread.new do\n        Object.send(:remove_const, :SHARED)\n        Object.const_set(:SHARED, \"after\")\n      end.join\n      p read_shared\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      \"first\"\n      \"second\"\n      \"shelf\"\n      \"restocked\"\n      \"uninitialized constant LATE\"\n      42\n      1\n      \"uninitialized constant GONE\"\n      NameError\n      \"Box::Inner\"\n      \"Box::Inner\"\n      \"before\"\n      \"after\"\n    OUT\n  end\n\n  it \"frozen nul literal cache\" do\n    result = ze0(<<~'RUBY')\n      # frozen_string_literal: true\n      # `fresh_receiver.delete(\"\\0\")` must not corrupt the receiver. Before the fix\n      # the frozen \"\\0\" literal was re-allocated on every call, and that allocation\n      # could trigger a GC that swept the (unrooted) fresh receiver before delete\n      # read it -- a use-after-free (doom's `data[8,8].delete(\"\\0\")` WAD name parse).\n      # Here the receiver has no NUL, so delete removes nothing: it still allocates a\n      # fresh string (delete always does), but the resulting bytes are unchanged.\n      out = []\n      8000.times do |i|\n        out << \"item\#{i % 100}\".delete(\"\\x00\")\n      end\n      puts out.length\n      puts out[0]\n      puts out.last\n      bad = 0\n      out.each_with_index { |s, i| bad += 1 unless s == \"item\#{i % 100}\" }\n      puts \"bad=\#{bad}\"\n\n      # Sibling-operand shape: a fresh string operand sits next to a frozen\n      # NUL-containing literal. The literal allocates on first evaluation (to fill its\n      # call-site cache), so subtree_may_allocate must flag it as allocating -- else\n      # the fresh operand is left unrooted and a GC during that first allocation frees\n      # it. `a + \"pad\\0\"` keeps \"pad\" (sp_str_plus stops the literal at its NUL).\n      def joinit(a)\n        a + \"pad\\x00\"\n      end\n      res = []\n      8000.times do |i|\n        res << joinit(\"head\#{i}\")\n      end\n      GC.start\n      # GC-safety check: the fresh \"head<i>\" prefix must survive (a corrupted operand\n      # would garble it). NUL-agnostic (via start_with?) so it does not depend on\n      # whether `+` keeps the frozen literal's trailing NUL.\n      sbad = 0\n      res.each_with_index { |s, i| sbad += 1 unless s.start_with?(\"head\#{i}pad\") }\n      puts \"scount=\#{res.size} sbad=\#{sbad}\"\n      puts res[0].delete(\"\\x00\")\n      puts res.last.delete(\"\\x00\")\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      8000\n      item0\n      item99\n      bad=0\n      scount=8000 sbad=0\n      head0pad\n      head7999pad\n    OUT\n  end\n\n  it \"raise names the snippet and the eval site\" do\n    result = ze0(<<~'RUBY', path: \"compiler/cache/a_raise_names_the_snippet_and_the_eval_site.rb\")\n      src = \"raise 'boom'\"\n      begin\n        eval(src)\n      rescue => e\n        puts e.backtrace.first(2)\n      end\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      (eval at compiler/cache/a_raise_names_the_snippet_and_the_eval_site.rb:3):1:in '<main>'\n      compiler/cache/a_raise_names_the_snippet_and_the_eval_site.rb:3:in 'Kernel#eval'\n    OUT\n  end\n\n  it \"snippet reaches its callers block\" do\n    result = ze0(<<~'RUBY', path: \"compiler/cache/a_snippet_reaches_its_callers_block.rb\")\n      # `yield`, `block_given?` and a bare `super` written at a snippet's own\n      # level belong to the method the `eval` was called from -- CRuby reads them\n      # off the caller's control frame. zeo publishes the home from every scope\n      # that lexically contains a run-time `eval`, so the snippet finds it\n      # whichever eval surface ran it.\n\n      YIELD = \"yield 7\"\n      GIVEN = \"block_given?\"\n      SUPER = \"super\"\n      DEF_S = \"defined?(super)\"\n      DEF_Y = \"defined?(yield)\"\n\n      def plain = eval(YIELD)\n      def given = eval(GIVEN)\n      def through_instance_eval = instance_eval(YIELD)\n      def through_class_eval = self.class.class_eval(YIELD)\n      def through_binding = eval(YIELD, binding)\n\n      p(plain { |x| x * 3 })\n      p given\n      p(given { })\n      p(through_instance_eval { |x| \"ie \#{x}\" })\n      p(through_class_eval { |x| \"ce \#{x}\" })\n      p(through_binding { |x| \"b \#{x}\" })\n\n      # A block re-publishes the home it inherited, so an intervening method that\n      # can eval cannot shadow it.\n      def helper\n        eval([\"1\", \"2\"].first)\n        yield\n      end\n      def outer\n        helper { p eval(YIELD) }\n      end\n      outer { |x| \"outer got \#{x}\" }\n\n      def nested\n        [1].map { [2].map { eval(YIELD) } }\n      end\n      p(nested { |x| x + 100 })\n\n      # A bare `super` forwards the enclosing method's own arguments.\n      class Base\n        def go(a, b = 2, *rest, k: 9) = [a, b, rest, k]\n      end\n      class Sub < Base\n        def go(a, b = 20, *rest, k: 90) = eval(SUPER)\n      end\n      p Sub.new.go(1)\n      p Sub.new.go(1, 2, 3, k: 4)\n\n      # `defined?` answers the same questions.\n      class DBase; def d = 1; end\n      class DSub < DBase; def d = eval(DEF_S); end\n      class DSolo; def d = eval(DEF_S); end\n      p DSub.new.d\n      p DSolo.new.d\n      p eval(DEF_S)\n      def dy = eval(DEF_Y)\n      p dy\n      p(dy { })\n\n      # A method that HAS no block raises `LocalJumpError` when the snippet\n      # yields; an `eval` called from a scope that can never have one -- the top\n      # level, a class body -- does not compile at all, which is CRuby's own\n      # `Invalid yield` and carries the eval's location as its whole backtrace.\n      def blockless = eval(YIELD)\n      begin\n        blockless\n      rescue LocalJumpError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n      begin\n        eval(YIELD)\n      rescue SyntaxError => e\n        puts \"\#{e.class}: \#{e.message}\"\n        p e.backtrace\n      end\n      class InBody\n        begin\n          eval(YIELD)\n        rescue SyntaxError => e\n          puts \"class body: \#{e.message}\"\n        end\n      end\n      # `defined?(yield)` asks rather than yields, so it answers nil instead.\n      p eval(DEF_Y)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      21\n      false\n      true\n      \"ie 7\"\n      \"ce 7\"\n      \"b 7\"\n      \"outer got 7\"\n      [[107]]\n      [1, 20, [], 90]\n      [1, 2, [3], 4]\n      \"super\"\n      nil\n      nil\n      nil\n      \"yield\"\n      LocalJumpError: no block given (yield)\n      SyntaxError: (eval at compiler/cache/a_snippet_reaches_its_callers_block.rb:74):1: Invalid yield\n      [\"(eval at compiler/cache/a_snippet_reaches_its_callers_block.rb:74)\"]\n      class body: (eval at compiler/cache/a_snippet_reaches_its_callers_block.rb:81):1: Invalid yield\n      nil\n    OUT\n  end\n\n  it \"snippet refines and uses at run time\" do\n    result = ze0(<<~'RUBY')\n      # Refinements are a compile-time decision in a program: a `refine` mints a\n      # holder the compiler registers, and a `using` rewrites the call sites in\n      # its lexical range. A snippet has neither -- its module is a run-time\n      # constant and what it refines lives in the running program's registry --\n      # so both go through the run time: `Module#refine` mints and marks the\n      # holder, and a `using` fills an activation slot every call site it covers\n      # reads.\n\n      module Outer\n        refine Integer do\n          def trip = self * 3\n        end\n      end\n\n      MINT = \"module Minted; refine String do; def shout = upcase + '!'; end; end\"\n      eval(MINT)\n      p Minted.refinements.size\n      p Minted.refinements.first.class\n      p \"hi\".respond_to?(:shout)\n\n      USE = [\n        \"using Outer\",\n        \"p 7.trip\",\n        \"p 7.respond_to?(:trip)\",\n        \"p 7.send(:trip)\",\n        \"p 7.method(:trip).owner.to_s\",\n        \"p [1, 2].map { |x| x.trip }\",\n        # A `def` written after the `using` sees it too: the slot outlives the\n        # call, exactly as CRuby's lexical activation outlives the eval.\n        \"def tripler(n) = n.trip\",\n      ].join(\"\\n\")\n      eval(USE)\n      p tripler(5)\n\n      # ... and nothing outside the snippet's own range sees it.\n      begin\n        3.trip\n      rescue NoMethodError\n        puts \"outside: NoMethodError\"\n      end\n\n      # A snippet that both mints and activates.\n      BOTH = [\n        \"module Both; refine Symbol do; def twice = [self, self]; end; end\",\n        \"using Both\",\n        \"p :a.twice\",\n      ].join(\"\\n\")\n      eval(BOTH)\n\n      # `using` answers the receiver it activated on.\n      ACT = \"using Outer\"\n      p eval(ACT)\n      class Host; end\n      p Host.class_eval(ACT)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      1\n      Refinement\n      false\n      21\n      true\n      21\n      \"#<refinement:Integer@Outer>\"\n      [3, 6]\n      15\n      outside: NoMethodError\n      [:a, :a]\n      main\n      Host\n    OUT\n  end\n\n  it \"snippets regexp literal has its own site\" do\n    result = ze0(<<~'RUBY')\n      # A non-interpolated regexp literal is ONE frozen object per site, cached in\n      # the runtime under an emitter-assigned id. A program's ids are dense from\n      # zero and minted by one compile; a run-time `eval` is compiled by a FRESH\n      # compiler that starts at zero again, so the two spaces collided and a site\n      # answered whichever pattern reached the cache first.\n      #\n      # It is silent: both sides get a working Regexp, just the wrong one. The\n      # tools found it -- the env-var check scanned every doc with a pattern\n      # from a run-time-required unit and reported the whole file as an undefined\n      # variable name.\n      #\n      # `flipflop::EVAL_BASE` and the `using` slots already hold their id spaces\n      # apart for exactly this reason; regexp literals and `attach_function` symbol\n      # sites did not.\n\n      text = \"a ZEO_ONE b ZEO_TWO c\"\n      names = /\\bZEO_[A-Z0-9_]+\\b/\n\n      # The snippet's own literals come first, so its site 0 is minted before the\n      # program reaches its own.\n      eval(%q{\n        def words(s) = s.scan(/\\w+/)\n        def digits(s) = s.scan(/\\d+/)\n      })\n\n      p text.scan(names)\n      p words(\"hi there\")\n      p digits(\"a1 b22 c333\")\n      p text.scan(names)\n      p text.scan(/\\bZEO_[A-Z0-9_]+\\b/)\n\n      # A second snippet must not collide with the first either.\n      eval(%q{ def caps(s) = s.scan(/[A-Z]+/) })\n      p caps(\"aBcDe\")\n      p words(\"still here\")\n\n      # The identity a per-site cache exists for: one site, one frozen object.\n      two = [text.scan(names), text.scan(names)]\n      p two.first == two.last\n      p names.frozen?\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [\"ZEO_ONE\", \"ZEO_TWO\"]\n      [\"hi\", \"there\"]\n      [\"1\", \"22\", \"333\"]\n      [\"ZEO_ONE\", \"ZEO_TWO\"]\n      [\"ZEO_ONE\", \"ZEO_TWO\"]\n      [\"B\", \"D\"]\n      [\"still\", \"here\"]\n      true\n      true\n    OUT\n  end\nend\n", "../../spec/compiler/fusion/blocks_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Fusion: blocks and yields\" do\n  it \"block forward recv typed\" do\n    _(ze0(<<~'RUBY')).must_answer \"1-basic\\n42\\n3-mixed\\n  body\\n4-thrice\\n4-thrice\\n4-thrice\\n5-arg=7\\n150\\n7-no-block\\ndone\\n\"\n      # Typed-receiver `recv.m { ... }` &block forwarding (Site B).\n      #\n      # Pre-fix `compile_object_method_expr` dropped the literal block: the\n      # call site emitted `sp_Cls_m(rc, 0)` and the binary segfaulted inside\n      # `sp_proc_call(NULL, ...)`. Fix: precompute `has_proc` from the\n      # callee's param types, pass it to `compile_typed_call_args` as the\n      # new `omit_trailing` 4th arg so the &block slot isn't padded with\n      # \"0\", then build a `bp`/`tail` that appends the proc literal after\n      # the regular args.\n\n      # 1. Basic: `recv.m { ... }` with arity-0 block.call.\n      class App\n        def run(&block)\n          block.call\n        end\n      end\n\n      App.new.run { puts \"1-basic\" }\n\n      # 2. block.call with one int arg, return value used.\n      class Doubler\n        def apply(x, &block)\n          block.call(x)\n        end\n      end\n\n      puts Doubler.new.apply(21) { |n| n * 2 }\n\n      # 3. Mixed: regular arg + &block, multiple stmts in method body.\n      class Logger\n        def log(label, &block)\n          puts label\n          block.call\n        end\n      end\n\n      Logger.new.log(\"3-mixed\") { puts \"  body\" }\n\n      # 4. Block invoked multiple times from inside the method.\n      class Repeater\n        def thrice(&block)\n          block.call\n          block.call\n          block.call\n        end\n      end\n\n      Repeater.new.thrice { puts \"4-thrice\" }\n\n      # 5. Block uses interpolation of its own argument. (Closure capture\n      #    over outer locals is a separate subsystem \xE2\x80\x94 out of scope here.)\n      class Wrapper\n        def go(n, &block)\n          block.call(n)\n        end\n      end\n\n      Wrapper.new.go(7) { |i| puts \"5-arg=\#{i}\" }\n\n      # 6. Block returns a value used by the method.\n      class Picker\n        def pick(&block)\n          block.call(10) + block.call(20)\n        end\n      end\n\n      puts Picker.new.pick { |n| n * 5 }\n\n      # 7. Method declares &block, call site provides none. The &block\n      #    slot must be filled with NULL \xE2\x80\x94 pre-fix `omit_trailing` dropped\n      #    the slot from the C call entirely, leaving an arity mismatch\n      #    between sp_Optional_maybe(sp_Optional *, sp_Proc *) and\n      #    sp_Optional_maybe(_t1).\n      class Optional\n        def maybe(&block)\n          puts \"7-no-block\"\n        end\n      end\n\n      Optional.new.maybe\n\n      puts \"done\"\n    RUBY\n  end\n\n  it \"block given inline call site\" do\n    result = ze0(<<~'RUBY')\n      # Issue #706: block_given? in a yield-using method, called from\n      # a site that either omits the block (zero-arg case emits\n      # `sp_f(NULL, NULL)`) or supplies a literal block (inline path\n      # correctly answers true).\n      def f\n        puts block_given?\n      end\n      f\n      f { }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      false\n      true\n    OUT\n  end\n\n  it \"block next nil typed map\" do\n    result = ze0(<<~'RUBY')\n      # A bare `next` yields nil, even when the block's tail is typed.\n      p [1, 2, 3].map { |v| next if v == 2; v }\n      p [\"a\", \"b\"].map { |v| next if v == \"a\"; v }\n      p [1.5, 2.5].map { |v| next if v > 2; v }\n      p 5.times.map { |v| next if v.even?; v }\n      p [1, 2, 3].map { |v| next if v == 2; v }.compact\n      p({ a: 1, b: 2 }.map { |k, v| next if v == 1; k })\n\n      def each_val\n        yield 1\n        yield 2\n      end\n      r = []\n      each_val { |v| next if v == 1; r << v }\n      p r\n\n      f = proc { |x| next if x; :kept }\n      p f.call(true), f.call(false)\n      p (1..4).map { |v| next if v == 3; v * 2 }\n      p 1.upto(3).map { |v| next if v == 1; v }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [1, nil, 3]\n      [nil, \"b\"]\n      [1.5, nil]\n      [nil, 1, nil, 3, nil]\n      [1, 3]\n      [nil, :b]\n      [2]\n      nil\n      :kept\n      [2, 4, nil, 8]\n      [nil, 2, 3]\n    OUT\n  end\n\n  it \"fiber yield inside an inline times block\" do\n    result = ze0(<<~'RUBY')\n      f = Fiber.new do\n        3.times do |i|\n          Fiber.yield i\n        end\n        :end\n      end\n      puts f.resume\n      puts f.resume\n      puts f.resume\n      puts f.resume\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      0\n      1\n      2\n      end\n    OUT\n  end\n\n  it \"fused block resets its own locals\" do\n    result = ze0(<<~'RUBY')\n      # A name first assigned INSIDE a fused block is fresh on every iteration,\n      # even though the splice shares the enclosing scope where it was hoisted.\n      out = []\n      3.times do |i|\n        x = i if i.odd?\n        out << x\n      end\n      p out\n      res = []\n      (1..4).each do |i|\n        seen = true if i > 2\n        res << [i, seen]\n      end\n      p res\n      total = 0\n      sum = []\n      4.times do |i|\n        total += i\n        tmp = i * 2 if i != 1\n        sum << tmp\n      end\n      p [total, sum]\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [nil, 1, nil]\n      [[1, nil], [2, nil], [3, true], [4, true]]\n      [6, [0, nil, 4, 6]]\n    OUT\n  end\n\n  it \"inline nested yield ivar self\" do\n    result = ze0(<<~'RUBY')\n      # Nested yield-method inlining: the outer inlined body calls another yielding\n      # method on a DIFFERENT receiver, passing its own (renamed) locals as args,\n      # and the caller's block reads the caller's ivars. The args must respect the\n      # outer inline's rename table and the spliced block body must resolve `self`\n      # to the CALLER, not the inner receiver (doom's compute_slide reading @map\n      # inside a block passed through each_nearby_linedef -> each_linedef_near).\n      class Grid\n        def initialize(cells)\n          @cells = cells\n        end\n\n        def each_cell_near(lo, hi)\n          @cells.each { |c| yield c if c >= lo && c <= hi }\n        end\n      end\n\n      class Walker\n        def initialize(grid, names)\n          @grid = grid\n          @names = names\n        end\n\n        def each_named(a, b)\n          unless @names.empty?\n            min_v = a < b ? a : b\n            max_v = a < b ? b : a\n            @grid.each_cell_near(min_v, max_v) { |c| yield c }\n            return\n          end\n          @grid.each_cell_near(a, b) { |c| yield c }\n        end\n\n        def collect(a, b)\n          out = []\n          each_named(a, b) do |c|\n            return out if c == 9\n            out << @names[c % @names.size]\n          end\n          out\n        end\n      end\n\n      g = Grid.new([2, 9, 4, 1, 7])\n      w = Walker.new(g, [\"red\", \"green\", \"blue\"])\n      puts w.collect(4, 1).inspect\n      puts w.collect(1, 9).inspect\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [\"blue\", \"green\", \"green\"]\n      [\"blue\"]\n    OUT\n  end\n\n  it \"inline yield deep nested self\" do\n    result = ze0(<<~'RUBY')\n      # Three levels of inlined yielding methods: process (inlined via its block),\n      # then @a.run and @b.run2 nested inside its spliced block. The deepest block\n      # reads @tag through Top's self while A's and B's receivers have overwritten\n      # the shared inline selfbuf. The caller-self fallback must survive by value,\n      # not alias the clobbered buffer, or @tag resolves against the wrong receiver.\n      class A\n        def initialize(v); @v = v; end\n        def run; yield @v; end\n      end\n      class B\n        def initialize(v); @v = v; end\n        def run2; yield @v; end\n      end\n      class Top\n        def initialize\n          @tag = \"TOP\"\n          @a = A.new(10)\n          @b = B.new(20)\n        end\n        def process\n          yield 0\n          @a.run do |x|\n            @b.run2 do |y|\n              puts \"\#{@tag}: \#{x} \#{y}\"\n            end\n          end\n        end\n      end\n      Top.new.process { |n| puts \"start \#{n}\" }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      start 0\n      TOP: 10 20\n    OUT\n  end\n\n  it \"inline yield method with return\" do\n    result = ze0(<<~'RUBY')\n      # A yielding method containing `return` must still inline at block call sites\n      # (a bailed inline emitted a plain call to a never-emitted symbol, an\n      # undefined-symbol link error: doom's PlayerPhysics#each_nearby_linedef).\n      # The method's own returns funnel to a per-inline exit; a `return` inside the\n      # caller's block still exits the CALLER.\n      class Walker\n        def initialize(items)\n          @items = items\n          @fast = false\n        end\n\n        def each_item(a, b)\n          unless @fast\n            @items.each { |it| yield it }\n            return\n          end\n          @items.each { |it| yield it if it >= a && it <= b }\n        end\n\n        def count_between(a, b)\n          n = 0\n          each_item(a, b) do |it|\n            return -1 if it < 0\n            n += 1\n          end\n          n\n        end\n      end\n\n      w = Walker.new([3, 1, 4, 1, 5])\n      puts w.count_between(1, 4)\n      w2 = Walker.new([3, -2, 9])\n      puts w2.count_between(0, 10)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      5\n      -1\n    OUT\n  end\n\n  it \"inline yield nested self ivar\" do\n    result = ze0(<<~'RUBY')\n      class Inner\n        def initialize(v)\n          @val = v\n        end\n        # a yielding method; inlined at the call site\n        def run\n          yield @val\n        end\n      end\n\n      class Outer\n        def initialize\n          @tag = \"outer\"\n          @inner = Inner.new(7)\n        end\n\n        # yielding method that, in its body, calls Inner#run with a block.\n        # The block reads @tag through Outer's self -- while Inner#run is inlined\n        # (its self is the Inner receiver). Nested inline must not clobber the\n        # caller's self used by the spliced block body.\n        def process\n          yield 1\n          @inner.run do |x|\n            puts \"\#{@tag}: \#{x}\"\n          end\n        end\n      end\n\n      o = Outer.new\n      o.process { |n| puts \"start \#{n}\" }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      start 1\n      outer: 7\n    OUT\n  end\n\n  it \"inline yield return side effect\" do\n    result = ze0(<<~'RUBY')\n      def side\n        puts \"side effect happened\"\n        42\n      end\n\n      def each_thing\n        puts \"before\"\n        yield 1\n        return side()\n        puts \"unreached\"\n      end\n\n      each_thing { |x| puts \"block \#{x}\" }\n      puts \"after\"\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      before\n      block 1\n      side effect happened\n      after\n    OUT\n  end\n\n  it \"inlined yield block param type\" do\n    result = ze0(<<~'RUBY')\n      # Issue #395 string-yield sub-variant. The previous fix only\n      # covered int-yielding `each` over a user class; a string-yielding\n      # variant still tripped a type mismatch (block param `k` got\n      # declared `mrb_int` at the parent scope, but the yield expansion\n      #