       def each\n          i = 0\n          while i < @nums.length\n            n = @nums[i]\n            yield n\n            i += 1\n          end\n          self\n        end\n      end\n\n      c = C.new\n      c.each { |n| puts n.to_s }   # 10 / 20 / 30\n\n      # B) `raise X unless Y` inside an inlined yield-method body\n      # (issue #392).\n      def measure\n        before = 1\n        yield\n        after = 2\n        raise \"fail\" unless after > before\n        true\n      end\n\n      measure { puts \"block\" }      # block\n      puts \"ok\"                     # ok\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      10\n      20\n      30\n      block\n      ok\n    OUT\n  end\n\n  it \"kwsplat yield inline bind\" do\n    result = ze0(<<~'RUBY')\n      # A yielding method called with a forwarded **hash: its keyword params must\n      # bind from the splatted hash (by runtime lookup) when the inlined body yields\n      # to the caller's block, not fall through to a fabricated default.\n      def add(a:, b:); yield(a + b); end\n      def run_add(h); add(**h) { |s| s * 10 }; end\n      p run_add({a: 1, b: 2})\n\n      # a keyword param with a default, partially covered by the splat\n      def sub(x:, y: 100); yield(x - y); end\n      def run_sub(h); sub(**h) { |s| s.abs }; end\n      p run_sub({x: 5})\n      p run_sub({x: 5, y: 3})\n\n      # mixed literal keyword and forwarded splat\n      def prod(a:, b:); yield(a * b); end\n      def run_prod(h); prod(a: 7, **h) { |s| s + 1 }; end\n      p run_prod({b: 6})\n\n      # string-valued keywords through the splat, interpolated in the yield\n      def label(name:, n:); yield(\"\#{name}=\#{n}\"); end\n      def run_label(h); label(**h) { |s| s.upcase }; end\n      p run_label({name: \"x\", n: 3})\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      30\n      95\n      2\n      43\n      \"X=3\"\n    OUT\n  end\n\n  it \"massign in inlined yield\" do\n    result = ze0(<<~'RUBY')\n      # A multiple assignment inside a method body that gets yield-inlined into its\n      # caller: every local-target emission (fixed targets, the rest, poly gets)\n      # must go through the inline rename table -- the declarations are renamed,\n      # so an unrenamed assignment references an undeclared C variable.\n      def pair\n        a, b = yield\n        [b, a]\n      end\n      p(pair { [1, 2] })\n      def rest_only\n        *r = *yield\n        r\n      end\n      p(rest_only { [3, 4] })\n      def spread\n        x, y, *z = *yield\n        [x, y, z]\n      end\n      p(spread { [1, 2, 3, 4] })\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [2, 1]\n      [3, 4]\n      [1, 2, [3, 4]]\n    OUT\n  end\n\n  it \"nested capture inlined times\" do\n    result = ze0(<<~'RUBY')\n      # An escaping closure can capture the param (and block-locals) of an INLINED\n      # `.times` block, even when that `.times` is itself nested inside another\n      # escaping block (Batch H). The `.times` body shares the enclosing scope,\n      # so each iteration's param is cell-wrapped fresh -- matching Ruby's\n      # per-iteration block-param binding -- and the nested closure captures it.\n\n      # param of a `.times` nested inside an `.each` block, captured by a lambda\n      store = []\n      [1, 2].each do |a|\n        store << ->() { a }\n        2.times do |b|\n          store << ->() { a + b }\n        end\n      end\n      store.each { |p| puts p.call }\n\n      # a `.times` block-local (|i; n|) captured by a nested block\n      labels = []\n      [10].each do |base|\n        3.times do |i; n|\n          n = base + i\n          labels << ->() { n }\n        end\n      end\n      labels.each { |p| puts p.call }\n\n      # the uncaptured fast path is untouched: break still works\n      total = 0\n      5.times { |i| total += i }\n      puts total\n      r = 5.times { |i| break i * 2 if i == 3 }\n      p r\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      1\n      1\n      2\n      2\n      2\n      3\n      10\n      11\n      12\n      10\n      6\n    OUT\n  end\n\n  it \"nested escaping block captures an inlined times param\" do\n    result = ze0(<<~'RUBY')\n      # An escaping closure capturing the param of an INLINED `.times` block.\n      # The `.times` body shares the enclosing scope, so the param is\n      # cell-wrapped per iteration -- fresh each turn, matching Ruby -- and the\n      # nested closure shares that cell, exactly like a real block param.\n      # Previously a clean compile-error scope-cut.\n      # a=1: {1}, {1+0}, {1+1}; a=2: {2}, {2+0}, {2+1}\n\n      store = []\n      [1, 2].each do |a|\n        store << ->() { a }\n        2.times do |b|\n          store << ->() { a + b }\n        end\n      end\n      store.each { |p| puts p.call }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      1\n      1\n      2\n      2\n      2\n      3\n    OUT\n  end\n\n  it \"proc capture inline block param\" do\n    result = ze0(<<~'RUBY')\n      # A proc created inside an INLINED iterator block, capturing the block's param\n      # (#2648): the body is wrapped in an immediately-called lambda that owns a\n      # renamed copy of the param, so each iteration captures a FRESH cell.\n      fs = [1, 2, 3].map { |i| ->{ i * 10 } }\n      p fs[0].call\n      p fs[1].call\n      p fs[2].call\n      procs = []\n      [7, 8].each { |v| procs << ->{ v } }\n      p procs[0].call\n      p procs[1].call\n      # blocks that do not create capturing procs are left alone\n      p [1, 2].map { |x| x + 1 }\n      s = 0\n      [1, 2, 3].each { |x| s += x }\n      p s\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      10\n      20\n      30\n      7\n      8\n      [2, 3]\n      6\n    OUT\n  end\n\n  it \"sibling block owns its local beside a fused loop\" do\n    result = ze0(<<~'RUBY')\n      line = \"mentions alpha and beta\"\n      names = [\"alpha\", \"gamma\"]\n\n      # The fused loop is the LOCAL-receiver `map` (a typed nomination).\n      p [\"typed\", [\"alpha\", \"gamma\"].map { |t| re = Regexp.new(t); ->(l) { !re.match(l).nil? } }.map { |m| m.call(line) }]\n      p [\"local\", names.map { |t| re = Regexp.new(t); ->(l) { !re.match(l).nil? } }.map { |m| m.call(line) }]\n\n      # The fused loop is a literal `times`, and it runs AFTER the sibling.\n      p [\"before\", [\"alpha\", \"gamma\"].map { |t| rx = Regexp.new(t); -> { rx.source } }.map(&:call)]\n      2.times { |i| rx = Regexp.new(\"zzz\"); f = -> { rx } }\n\n      # A fused body's own local never reaches the scope around it.\n      2.times { |i| kept = i * 10 }\n      p defined?(kept)\n\n      # ...but a name the scope assigned FIRST is shared, as ruby shares it.\n      shared = \"outer\"\n      2.times { |i| shared = \"in\#{i}\" }\n      p shared\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [\"typed\", [true, false]]\n      [\"local\", [true, false]]\n      [\"before\", [\"alpha\", \"gamma\"]]\n      nil\n      \"in1\"\n    OUT\n  end\n\n  it \"yield inline arg caller context\" do\n    result = ze0(<<~'RUBY')\n      # An argument to a yielding (inlined) method is call-site code: it must\n      # resolve against the CALLER's self and class, not the receiver's. Here\n      # `interval` is the caller Widget's attr_reader, interpolated into the\n      # cache key passed to Cache#fetch. Regression: the receiver-context\n      # switch happened before argument binding, so `interval` resolved (and\n      # was invoked) against the Cache receiver instead of the Widget caller.\n      class Cache\n        def fetch(key)\n          @store ||= {}\n          return @store[key] if @store.key?(key)\n          @store[key] = yield\n        end\n      end\n\n      class Widget\n        def initialize(name)\n          @name = name\n        end\n\n        def interval\n          @name\n        end\n\n        def compute\n          # `interval` (caller's reader) is in the ARG; the block is caller code too.\n          Cache.new.fetch(\"data_\#{interval}\") { \"value_for_\#{interval}\" }\n        end\n      end\n\n      puts Widget.new(\"hourly\").compute\n      puts Widget.new(\"daily\").compute\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      value_for_hourly\n      value_for_daily\n    OUT\n  end\n\n  it \"yield inline ctor self\" do\n    result = ze0(<<~'RUBY')\n      # A yielding `initialize` is inlined at the `new { }` call site. Its body\n      # runs in the CONSTRUCTED class's context, so an implicit-self call there\n      # (`setup`) must resolve against Builder, not the caller Client \xE2\x80\x94 while\n      # constructor arguments stay call-site code (bound in the caller's\n      # context, handled separately).\n      class Builder\n        def initialize(seed)\n          @seed = seed\n          setup                 # implicit-self call inside the yielding initialize\n          yield self\n        end\n\n        def setup\n          @ready = true\n        end\n\n        def ready?\n          @ready\n        end\n\n        def seed\n          @seed\n        end\n      end\n\n      class Client\n        def base\n          100\n        end\n\n        def make\n          # `base` (caller's method) is an ARG => caller context;\n          # `setup` inside initialize => constructed-class context.\n          Builder.new(base) { |b| b }\n        end\n      end\n\n      w = Client.new.make\n      p w.ready?\n      p w.seed\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      true\n      100\n    OUT\n  end\n\n  it \"yield inline divergent accumulator\" do\n    result = ze0(<<~'RUBY')\n      # A yield-inlined method that accumulates yield results into an array it\n      # returns (map-style) must widen that array to poly when its callers pass\n      # blocks of divergent value type -- otherwise an object-returning block's\n      # elements land in an int-sized accumulator (#2454). The scalar round-trip\n      # for a method that returns the yield value directly is unaffected.\n      class Rel\n        def map\n          out = []\n          [1, 2].each { |i| out << (yield i) }\n          out\n        end\n      end\n      class T\n        attr_accessor :n\n        def initialize(n); @n = n; end\n      end\n      def sum_ints; Rel.new.map { |i| i * 2 }; end\n      def make_objs(counts); Rel.new.map { |i| o = T.new(counts[i]); o }; end\n      def make_strs; Rel.new.map { |i| \"v\#{i}\" }; end\n      p sum_ints\n      p make_objs({ 1 => 10, 2 => 20 }).map { |o| o.n }\n      p make_strs\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [2, 4]\n      [10, 20]\n      [\"v1\", \"v2\"]\n    OUT\n  end\n\n  it \"yield inline divergent block map\" do\n    result = ze0(<<~'RUBY')\n      # A yield-inline wrapper called from sites whose blocks return DIFFERENT types:\n      # the collector the inner iterator builds must hold poly elements. One shared\n      # inlined body cannot size it for both an Integer- and a String-returning block\n      # -- whichever site is analyzed first would settle the slot and the other would\n      # emit into it (#2457, same family as the `acc << yield(x)` case in #2454).\n      class Row\n        def initialize(i, c); @i = i; @c = c; end\n        def id; @i; end\n        def category; @c; end\n      end\n      class Relation\n        def initialize(rows); @rows = rows; end\n        def to_a; @rows; end\n        def map; to_a.map { |x| yield x }; end\n      end\n      r = Relation.new([Row.new(1, \"news\"), Row.new(2, \"ask\")])\n      puts r.map { |x| x.category }.join(\" \")\n      p r.map { |x| x.id }\n      p r.map { |x| x.id }.length\n      p r.map { |x| x.id.to_f }\n\n      # a wrapper whose sites all agree keeps its concrete element type\n      class IntsOnly; def map; [1, 2].map { |x| yield x }; end; end\n      i = IntsOnly.new\n      p i.map { |x| x + 1 }\n      p i.map { |x| x * 2 }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      news ask\n      [1, 2]\n      2\n      [1.0, 2.0]\n      [2, 3]\n      [2, 4]\n    OUT\n  end\n\n  it \"yield inline receiver self\" do\n    _(ze0(<<~'RUBY')).must_answer \"[12, 3]\\n\"\n      # A yielding method is inlined at its block call site. The inlined body\n      # runs in the RECEIVER's class context, so an implicit-self call inside\n      # it (`to_a` / `size` below, both defined on Relation) must resolve\n      # against Relation \xE2\x80\x94 not against the CALLER's class (Paginator), which\n      # has no such method. Regression: the inline bound `self` to the\n      # receiver but left the emitting-class context as the caller's.\n      class Relation\n        def initialize(items)\n          @items = items\n        end\n\n        def to_a\n          @items\n        end\n\n        def size\n          @items.length\n        end\n\n        # yields; also makes two implicit-self calls (to_a, size)\n        def each_doubled\n          to_a.each { |x| yield x * 2 }\n          size\n        end\n      end\n\n      class Paginator\n        def run\n          r = Relation.new([1, 2, 3])\n          total = 0\n          n = r.each_doubled { |v| total += v }\n          [total, n]\n        end\n      end\n\n      p Paginator.new.run\n    RUBY\n  end\n\n  it \"yield typed hash block local\" do\n    result = ze0(<<~'RUBY')\n      # `yield <typed-hash>` from a top-level method should propagate the\n      # hash's type to the caller's block-param local. Pre-fix\n      # block_param_type_at returned `int` for no-recv user yield methods\n      # (only the receiver-typed `arr.each` / `c.each` arms had yield-arg\n      # lookup wired up), so the block-local was declared `mrb_int` and\n      # the typed pointer was silently coerced to an int slot. Downstream\n      # `row[\"k\"]` then dispatched on int and folded to 0. Issue #628.\n\n      def emit_rows\n        i = 0\n        while i < 2\n          row = {\"k\" => \"v\" + i.to_s}\n          yield row\n          i += 1\n        end\n      end\n\n      out = \"\"\n      emit_rows do |row|\n        out = out + row[\"k\"] + \",\"\n      end\n      puts out\n\n      # Same shape via a helper that returns the typed hash.\n      def make_h(s)\n        {\"k\" => s}\n      end\n\n      def emit_rows_via_helper\n        i = 0\n        while i < 2\n          yield make_h(\"v\" + i.to_s)\n          i += 1\n        end\n      end\n\n      out2 = \"\"\n      emit_rows_via_helper do |row|\n        out2 = out2 + row[\"k\"] + \",\"\n      end\n      puts out2\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      v0,v1,\n      v0,v1,\n    OUT\n  end\nend\n", "../../spec/compiler/fusion/control_flow_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Fusion: control flow\" do\n  it \"blocks times inlines to a native loop\" do\n    result = ze0(<<~'RUBY')\n      3.times do |i|\n        puts i\n      end\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      0\n      1\n      2\n    OUT\n  end\n\n  it \"destructure typed ptr array return\" do\n    result = ze0(<<~'RUBY')\n      # Top-level `y, z = call_returning_pair_of_objs` segfaulted pre-fix:\n      # collect_scoped_multi_const pushed every top-level MultiWriteNode\n      # into @multi_const_inits, even when no target was a constant. The\n      # codegen loop then planted a pre-body `_t = call(lv_a, lv_b);` emit\n      # before the locals it reads from had been assigned. With both\n      # args still NULL the inlined method body deref'd NULL and crashed.\n      # Issue #630.\n\n      class Mat\n        attr_accessor :nrows, :ncols\n        def initialize(nrows, ncols)\n          @nrows = nrows\n          @ncols = ncols\n        end\n        def matmul(other)\n          Mat.new(@nrows, other.ncols)\n        end\n      end\n\n      def fwd(w, x)\n        y = w.matmul(x)\n        z = w.matmul(x)\n        [y, z]\n      end\n\n      w = Mat.new(3, 4)\n      x = Mat.new(4, 1)\n      y, z = fwd(w, x)\n      puts y.nrows\n      puts z.ncols\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      3\n      1\n    OUT\n  end\n\n  it \"fused loop binds every block parameter shape\" do\n    result = ze0(<<~'RUBY')\n      # `3.times`, `(a..b).each` and `arr.each` fuse into a counted loop when the\n      # block takes at most one required parameter. Ruby binds every other shape\n      # happily -- `3.times { |a, b| }` gives `b` nil -- so those take the ordinary\n      # block send instead of being refused.\n      #\n      # The emitter used to check the parameter shape AFTER deciding to splice, and\n      # refused what it found. Found 2026-08-21 while looking for a live refusal to\n      # pin a diagnostics test on.\n      3.times { |a, b| p [a, b] }\n      (1..3).each { |a, b| p [a, b] }\n      [10, 20].each { |a, b| p [a, b] }\n\n      3.times { |a,| p a }\n      3.times { |*a| p a }\n      3.times { |a, (b, c)| p [a, b, c] }\n      3.times { |a, *rest| p [a, rest] }\n      3.times { |a, b: 9| p [a, b] }\n      3.times { |a, &blk| p [a, blk] }\n\n      [[1, 2], [3, 4]].each { |a, b| p [a, b] }\n      [[1, 2], [3, 4]].each { |(a, b)| p [a, b] }\n\n      # The one-parameter shapes still fuse, and answer the same.\n      3.times { |i| p i }\n      (1..3).each { |i| p i }\n      [7, 8].each { |e| p e }\n      3.times { p :none }\n\n      # The loop's own value survives either path.\n      p 3.times { |a, b| }\n      p((1..3).each { |a, b| })\n      p [1, 2].each { |a, b| }\n\n      # A block-local and a closure capture, on the non-fused path.\n      seen = []\n      3.times { |a, b; tmp| tmp = a * 2; seen << tmp }\n      p seen\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [0, nil]\n      [1, nil]\n      [2, nil]\n      [1, nil]\n      [2, nil]\n      [3, nil]\n      [10, nil]\n      [20, nil]\n      0\n      1\n      2\n      [0]\n      [1]\n      [2]\n      [0, nil, nil]\n      [1, nil, nil]\n      [2, nil, nil]\n      [0, []]\n      [1, []]\n      [2, []]\n      [0, 9]\n      [1, 9]\n      [2, 9]\n      [0, nil]\n      [1, nil]\n      [2, nil]\n      [1, 2]\n      [3, 4]\n      [1, 2]\n      [3, 4]\n      0\n      1\n      2\n      1\n      2\n      3\n      7\n      8\n      :none\n      :none\n      :none\n      3\n      1..3\n      [1, 2]\n      [0, 2, 4]\n    OUT\n  end\n\n  it \"fused loop binds its names per iteration\" do\n    result = ze0(<<~'RUBY')\n      # `n.times { |i| }` and `(a..b).each { |i| }` on a LITERAL receiver splice\n      # into a counted loop with no frame of their own. Ruby still binds the block's\n      # names PER INVOCATION, so a closure built in one iteration must keep what it\n      # captured when the next iteration rebinds -- the splice cannot hand every\n      # closure one shared slot.\n      #\n      # Giving the spliced param a plain slot means REFUSING any escaping block\n      # that captures it (\"the shadow dies with the loop\"), which takes out\n      # `3.times { |i| Process.fork { exit i } }` among others. A name a closure\n      # escapes with now gets a fresh cell each iteration; a name nothing escapes\n      # with keeps the slot, and the uncaptured loop is untouched.\n\n      # --- the parameter ----------------------------------------------------------\n      procs = []\n      3.times { |i| procs << -> { i } }\n      p procs.map(&:call)\n\n      ranged = []\n      (1..3).each { |i| ranged << -> { i * 10 } }\n      p ranged.map(&:call)\n\n      # --- a name first assigned inside the body ---------------------------------\n      doubled = []\n      3.times do |i|\n        n = i * 2\n        doubled << -> { n }\n      end\n      p doubled.map(&:call)\n\n      # --- an explicit block-local (`|i; n|`) ------------------------------------\n      n = \"outer\"\n      labels = []\n      3.times do |i; n|\n        n = \"in\#{i}\"\n        labels << -> { n }\n      end\n      p labels.map(&:call)\n      p n\n\n      # --- a block-local that is never assigned is nil each time ------------------\n      seen = []\n      2.times { |i; fresh| seen << fresh; fresh = i }\n      p seen\n\n      # --- a conditional first assignment does not carry over --------------------\n      carried = []\n      3.times do |i|\n        once = i if i == 1\n        carried << once\n      end\n      p carried\n\n      # --- the param shadows an enclosing local of the same name -----------------\n      i = :outer\n      2.times { |i| }\n      p i\n\n      # --- nested splices: each level binds its own ------------------------------\n      pairs = []\n      2.times do |a|\n        2.times do |b|\n          pairs << -> { [a, b] }\n        end\n      end\n      p pairs.map(&:call)\n\n      # --- a splice inside a real block ------------------------------------------\n      mixed = []\n      [10, 20].each do |base|\n        2.times { |k| mixed << -> { base + k } }\n      end\n      p mixed.map(&:call)\n\n      # --- the uncaptured fast path is untouched ---------------------------------\n      total = 0\n      5.times { |x| total += x }\n      p total\n\n      acc = []\n      (0..4).each do |x|\n        next if x == 2\n        break if x == 4\n        acc << x\n      end\n      p acc\n\n      # --- a closure captured mid-loop sees the value at capture time ------------\n      snapshots = []\n      3.times do |i|\n        snapshots << -> { i }\n        i = i + 100\n      end\n      p snapshots.map(&:call)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [0, 1, 2]\n      [10, 20, 30]\n      [0, 2, 4]\n      [\"in0\", \"in1\", \"in2\"]\n      \"outer\"\n      [nil, nil]\n      [nil, 1, nil]\n      :outer\n      [[0, 0], [0, 1], [1, 0], [1, 1]]\n      [10, 11, 20, 21]\n      10\n      [0, 1, 3]\n      [100, 101, 102]\n    OUT\n  end\n\n  it \"fused loop guard fails at run time\" do\n    result = ze0(<<~'RUBY', env: {\"ZEO_RT_LEAKCHECK\" => \"1\"})\n\n      # A fused `arr.each` splice is guarded twice at run time -- the receiver's\n      # tag must be Array, and `zeo_rt_iter_inline_ok_for` must still hold -- and\n      # the FALLBACK arm is what runs when either fails. That arm reaches the same\n      # epilogue as the inline one, so every slot the epilogue releases has to be\n      # initialised on it too.\n      #\n      # `Array.send(:define_method, :each)` is what makes the second guard answer\n      # false, so both arms run here in one program: the first call takes the\n      # inline arm, the second the fallback. Before slot initialization moved to\n      # the entry block, the block parameter's slot was nil-initialised INSIDE the\n      # inline arm, so the second call released a slot holding stack garbage.\n      # `tests/compiled_code_releases_a_dead_slot.rb` has the mechanism.\n      #\n      # A RUN-TIME redefinition, deliberately. A compile-time `class Array; def\n      # each` reaches backwards and makes the FIRST call answer 30 as well --\n      # that is `tests/gaps/a_later_def_on_a_builtin_reaches_back.rb`, a separate\n      # gap this file must not depend on.\n      #\n      # Runs under `ZEO_RT_LEAKCHECK=1`, which is what makes it a memory-safety\n      # test rather than an output test.\n      #\n      # HONEST LIMIT: this golden does NOT reproduce the bug on the pre-fix\n      # emitter -- it was tried, and it came out clean. The released bytes are\n      # stack garbage, and a short frame leaves benign garbage behind. What this\n      # file adds is coverage of the path, so a LOUD failure on it is caught.\n\n      def sum_of(a)\n        total = 0\n        a.each { |x| total += x }\n        total\n      end\n\n      p sum_of([1, 2, 3])\n\n      Array.send(:define_method, :each) do |&b|\n        b.call(10)\n        b.call(20)\n        self\n      end\n\n      p sum_of([1, 2, 3])\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      6\n      30\n    OUT\n  end\n\n  it \"isa guarded return narrow\" do\n    result = ze0(<<~'RUBY')\n      module Addressable\n        class URI\n          attr_reader :host\n          def self.parse(uri)\n            return uri if uri.is_a?(URI)\n            new(uri.to_s)\n          end\n          def initialize(host)\n            @host = host\n          end\n          def join(other)\n            URI.new(URI.parse(other.to_s).host)\n          end\n        end\n      end\n      j = Addressable::URI.parse(\"h\").join(\"c\")\n      puts j.host\n\n      # a genuinely mixed call profile still works (param widens to poly)\n      class Wrapper\n        attr_reader :v\n        def self.wrap(x)\n          return x if x.is_a?(Wrapper)\n          new(x)\n        end\n        def initialize(v) = @v = v\n      end\n      a = Wrapper.wrap(\"s\")\n      b = Wrapper.wrap(a)\n      p a.v\n      p b.v\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      c\n      \"s\"\n      \"s\"\n    OUT\n  end\n\n  it \"next splat typed map\" do\n    _(ze0(<<~'RUBY')).must_answer \"[1, [2, 2], 3]\\n\"\n      # A splat-valued `next` contributes the array value to the map result.\n      p (1..3).map { |v| next *[v, v] if v == 2; v }\n    RUBY\n  end\n\n  it \"nil time return guard narrow\" do\n    result = ze0(<<~'RUBY')\n      # A method returning `nil | Time` types poly (Time has no first-class\n      # nullable slot). A caller branch guarded by `a.nil?` or `a` truthiness\n      # narrows reads of the local to Time inside the non-nil arm (read-site\n      # unbox, the #1661 machinery on the caller side). Reassigned locals and\n      # reads outside a guard stay poly and keep the honest NoMethodError.\n      module M\n        def self.maybe_time(s)\n          return nil if s.nil?\n          Time.at(0).utc\n        end\n      end\n\n      # if a.nil? ... else (the issue's shape)\n      a = M.maybe_time(\"x\")\n      if a.nil?\n        puts \"branch-nil\"\n      else\n        puts \"branch-time\"\n        y = a.year\n        puts \"year:\" + y.to_s\n      end\n\n      # unless a.nil? (the silent variant from the report)\n      b = M.maybe_time(\"x\")\n      unless b.nil?\n        puts b.year.to_s\n      end\n\n      # bare truthiness guard, method with an argument\n      c = M.maybe_time(\"x\")\n      if c\n        puts c.strftime(\"%Y-%m-%d\")\n      end\n\n      # the nil path through the same guards\n      d = M.maybe_time(nil)\n      if d.nil?\n        puts \"d-nil\"\n      else\n        puts d.year\n      end\n      unless d.nil?\n        puts \"not-reached\"\n      end\n\n      # chained use inside the arm\n      e = M.maybe_time(\"x\")\n      unless e.nil?\n        puts e.month + e.day\n      end\n      puts \"end\"\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      branch-time\n      year:1970\n      1970\n      1970-01-01\n      d-nil\n      2\n      end\n    OUT\n  end\n\n  it \"safe nav typed receiver\" do\n    result = ze0(<<~'RUBY')\n      class Combat\n        def initialize\n          @count = 3\n          @name = \"shotgun\"\n        end\n\n        def sprites\n          @count * 2\n        end\n\n        def update(n)\n          @count += n\n          @count\n        end\n\n        def name\n          @name\n        end\n      end\n\n      class Player\n        def initialize(armed)\n          @combat = Combat.new if armed\n        end\n\n        def combat\n          @combat\n        end\n\n        def tick\n          p @combat&.sprites\n          p @combat&.update(1)\n        end\n      end\n\n      alive = Player.new(true)\n      alive.tick\n      alive.tick\n\n      dead = Player.new(false)\n      dead.tick\n\n      p alive.combat&.name&.length\n      p dead.combat&.name&.length\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      6\n      4\n      8\n      5\n      nil\n      nil\n      7\n      nil\n    OUT\n  end\nend\n", "../../spec/compiler/fusion/dispatch_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Fusion: dispatch\" do\n  it \"dispatch inline cache invalidation\" do\n    result = ze0(<<~'RUBY')\n      # A dynamic call site remembers what the receiver's class resolved to, so\n      # anything that can change that answer has to be seen. Every case below WARMS\n      # the site first -- a cache that was never filled would pass these by accident.\n\n      class Greeter\n        def hello = \"plain\"\n      end\n\n      def call_hello(g) = g.hello\n\n      warm = Greeter.new\n      100.times { call_hello(warm) }\n      p call_hello(warm)\n\n      # A runtime `define_method` replaces it, on the warmed receiver and a fresh one.\n      Greeter.define_method(:hello) { \"redefined\" }\n      p call_hello(warm)\n      p call_hello(Greeter.new)\n\n      # A per-object singleton is closer than the class.\n      solo = Greeter.new\n      100.times { call_hello(solo) }\n      def solo.hello = \"singleton\"\n      p call_hello(solo)\n      p call_hello(Greeter.new)\n\n      # `extend` splices a module ahead of nothing, but `prepend` beats the class.\n      module Loud\n        def hello = \"LOUD\"\n      end\n      ext = Greeter.new\n      100.times { call_hello(ext) }\n      ext.extend(Loud)\n      p call_hello(ext)\n\n      class Prepended\n        def hello = \"base\"\n      end\n      pre = Prepended.new\n      100.times { call_hello(pre) }\n      Prepended.prepend(Loud)\n      p call_hello(pre)\n      p call_hello(Prepended.new)\n\n      # A second class at the same site: the cache holds one, the other must still\n      # resolve correctly.\n      class Other\n        def hello = \"other\"\n      end\n      mixed = [Greeter.new, Other.new, Greeter.new, Other.new]\n      p mixed.map { |m| call_hello(m) }\n\n      # The same site over builtin VALUE receivers, which resolve by a different\n      # route but share the cache.\n      def stringify(v) = v.to_s\n      100.times { stringify(1) }\n      p [stringify(1), stringify(2.5), stringify(:sym), stringify([1, 2]), stringify(nil)]\n\n      # `undef` retracts a name after the site is warm.\n      class Fragile\n        def hello = \"here\"\n      end\n      f = Fragile.new\n      100.times { call_hello(f) }\n      class Fragile\n        undef_method :hello\n      end\n      begin\n        call_hello(f)\n      rescue NoMethodError\n        p :undefined\n      end\n\n      # An alias added at runtime resolves through the same site.\n      class Greeter\n        def real = \"real\"\n      end\n      g2 = Greeter.new\n      100.times { call_hello(g2) }\n      Greeter.alias_method :hello, :real\n      p call_hello(g2)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      \"plain\"\n      \"redefined\"\n      \"redefined\"\n      \"singleton\"\n      \"redefined\"\n      \"LOUD\"\n      \"LOUD\"\n      \"LOUD\"\n      [\"redefined\", \"other\", \"redefined\", \"other\"]\n      [\"1\", \"2.5\", \"sym\", \"[1, 2]\", \"\"]\n      :undefined\n      \"real\"\n    OUT\n  end\n\n  it \"implicit alloc site cache helper specialization\" do\n    result = ze0(<<~'RUBY')\n      RowA = Struct.new(:id, :name)\n      RowB = Struct.new(:id, :label)\n\n      class RecordCache\n        def initialize\n          @records = []\n          @loaded = false\n        end\n\n        def loaded?\n          @loaded\n        end\n\n        def read_all\n          @records\n        end\n\n        def replace(records)\n          @records = records\n          @loaded = true\n          @records\n        end\n\n        def mark_unloaded\n          @loaded = false\n        end\n\n        def find_by_id(id)\n          index = 0\n          while index < @records.length\n            record = @records[index]\n            return record if record.id == id\n\n            index = index + 1\n          end\n          nil\n        end\n\n        def relationship_exists(id)\n          !find_by_id(id).nil?\n        end\n      end\n\n      class AStore\n        def initialize\n          @cache = RecordCache.new\n        end\n\n        def load_records\n          records = [RowA.new(0, \"\")]\n          records.delete_at(0)\n          records << RowA.new(1, \"alpha\")\n          records << RowA.new(2, \"next\")\n          records\n        end\n\n        def read_all\n          return @cache.read_all if @cache.loaded?\n\n          @cache.replace(load_records)\n        end\n\n        def find_by_id(id)\n          read_all\n          @cache.find_by_id(id)\n        end\n\n        def relationship_exists(id)\n          read_all\n          @cache.relationship_exists(id)\n        end\n      end\n\n      class BStore\n        def initialize\n          @cache = RecordCache.new\n        end\n\n        def load_records\n          records = [RowB.new(0, \"\")]\n          records.delete_at(0)\n          records << RowB.new(1, \"first\")\n          records << RowB.new(2, \"beta\")\n          records\n        end\n\n        def read_all\n          return @cache.read_all if @cache.loaded?\n\n          @cache.replace(load_records)\n        end\n\n        def find_by_id(id)\n          read_all\n          @cache.find_by_id(id)\n        end\n\n        def relationship_exists(id)\n          read_all\n          @cache.relationship_exists(id)\n        end\n      end\n\n      store_a = AStore.new\n      store_b = BStore.new\n\n      puts store_a.read_all[0].name\n      puts store_b.read_all[1].label\n      puts store_a.find_by_id(2).name\n      puts store_b.find_by_id(1).label\n      puts store_a.relationship_exists(2)\n      puts store_b.relationship_exists(3)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      alpha\n      beta\n      next\n      first\n      true\n      false\n    OUT\n  end\n\n  it \"inlined accessor takes the ordinary dispatch\" do\n    result = ze0(<<~'RUBY')\n      # The widened sweep behind `an_inlined_accessor_ignores_a_later_redefinition`:\n      # every route by which a run-time definition can displace an accessor the\n      # compiler folded to an ivar read. Each pair below reads the same accessor\n      # from INSIDE the class and from outside, so a fold that outlived its\n      # redefinition shows as two answers for one method.\n      #\n      # The routes: a reader and a writer replaced by `define_method`; the same\n      # name replaced on a SUBCLASS, where the superclass keeps its own answer; a\n      # `remove_method` followed by an `include` that supplies the name from a\n      # module; and an `alias_method` over the accessor.\n\n      class A\n        attr_accessor :v\n        def initialize = @v = 1\n        def read = v\n        def write(x) = (self.v = x)\n      end\n      a = A.new\n      p a.read\n      A.class_eval { define_method(:v) { 99 } }\n      p a.read\n      A.class_eval { define_method(:v=) { |x| @v = x * 10 } }\n      p a.write(5)\n      p a.instance_variable_get(:@v)\n\n      class B\n        attr_reader :w\n        def initialize = @w = 2\n        def read = w\n      end\n      class C < B\n        def read2 = w\n      end\n      c = C.new\n      p c.read\n      p c.read2\n      C.class_eval { define_method(:w) { :sub } }\n      p c.read\n      p c.read2\n      p B.new.read\n\n      module M\n        def z = :module_z\n      end\n      class D\n        attr_reader :z\n        def initialize = @z = 3\n        def read = z\n      end\n      d = D.new\n      p d.read\n      D.class_eval { remove_method :z }\n      D.include(M)\n      p d.read\n\n      class E\n        attr_reader :q\n        def initialize = @q = 4\n        def read = q\n      end\n      e = E.new\n      p e.read\n      E.class_eval { alias_method :q, :object_id }\n      p e.read.is_a?(Integer)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      1\n      99\n      5\n      50\n      2\n      2\n      :sub\n      :sub\n      2\n      3\n      :module_z\n      4\n      true\n    OUT\n  end\n\n  it \"is a against a poly typed method parameter\" do\n    result = ze0(<<~'RUBY')\n      # A method PARAMETER is always `TyKind::Poly` (zeo never infers a\n      # param's type from its call sites) -- this exercises the runtime\n      # `zeo_rt::is_a` fallback (via the new universal `RubyValue::class_id`)\n      # rather than the static ancestors-constant-fold path.\n\n      class Checker\n        def check(v)\n          v.is_a?(Integer)\n        end\n      end\n      c = Checker.new\n      puts c.check(5)\n      puts c.check(\"hi\")\n      puts c.check([1, 2])\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      true\n      false\n      false\n    OUT\n  end\n\n  it \"nil guard narrows int or nil\" do\n    result = ze0(<<~'RUBY')\n      # #550. Mirror of d3ee2b2 (#493) for the nil-vs-not case on\n      # int|nil locals. After `return -1 if h.nil?`, the rest of the\n      # scope sees `h` as non-nil; for a local whose writer was a\n      # known int-or-nil source (String#index, rindex, find_index),\n      # the non-nil arm is mrb_int. The function's return type\n      # narrows accordingly, and the trailing `h + 1` lowers via\n      # integer arithmetic on the unboxed payload instead of routing\n      # through sp_poly_add.\n      #\n      # Cascade: the 0210389 String#index return-type change widened\n      # all downstream consumers to sp_RbVal. Before this fix, every\n      # `h = s.index(needle); ...; h + 1` had to be hand-wrapped in a\n      # pure-int helper (Tep.str_find) to avoid the poly widening.\n      # With the nil-guard narrow, the idiomatic form works directly.\n      #\n      # Discriminator: `lookup` consumes find_or_neg's return as an\n      # int-typed array index. Pre-fix the function returns sp_RbVal\n      # and arr[poly] does not compile cleanly (spinel emits no\n      # implicit poly->int unbox at the index site). Post-fix the\n      # return is mrb_int and arr[i] is direct integer indexing.\n\n      ARR = [10, 20, 30, 40, 50, 60]\n\n      def find_or_neg(s, needle)\n        h = s.index(needle)\n        return -1 if h.nil?\n        h + 1\n      end\n\n      def lookup(s, needle)\n        i = find_or_neg(s, needle)\n        return 0 if i < 0\n        ARR[i]\n      end\n\n      puts find_or_neg(\"abcdef\", \"b\")\n      puts find_or_neg(\"abcdef\", \"z\")\n      puts lookup(\"abcdef\", \"b\")\n      puts lookup(\"abcdef\", \"a\")\n      puts lookup(\"abcdef\", \"z\")\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      2\n      -1\n      30\n      20\n      0\n    OUT\n  end\n\n  it \"nil guard param narrow\" do\n    result = ze0(<<~'RUBY')\n      def up(s)\n        return \"nil\" if s.nil?\n        s.upcase\n      end\n      puts up(\"hi\")\n      puts up(nil)\n\n      def fmt(t)\n        return \"null\" if t.nil?\n        t.strftime(\"%Y\")\n      end\n      puts fmt(Time.at(0).utc)\n      puts fmt(nil)\n\n      def inc(x)\n        return -1 if x.nil?\n        x + 1\n      end\n      p inc(41)\n      p inc(nil)\n\n      def two(a, b)\n        return \"a-nil\" if a.nil?\n        return \"b-nil\" if b.nil?\n        a + b.upcase\n      end\n      puts two(nil, \"x\")\n      puts two(\"x\", nil)\n      puts two(\"x-\", \"y\")\n\n      def blocky(s)\n        return 0 if s.nil?\n        n = 0\n        2.times { n += s.length }\n        n\n      end\n      p blocky(\"abc\")\n      p blocky(nil)\n\n      def reassigned(s)\n        return \"n\" if s.nil?\n        s = nil if s == \"z\"\n        s.to_s\n      end\n      puts reassigned(\"a\")\n      puts reassigned(\"z\")\n      puts reassigned(nil)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      HI\n      nil\n      1970\n      null\n      42\n      -1\n      a-nil\n      b-nil\n      x-Y\n      6\n      0\n      a\n\n      n\n    OUT\n  end\n\n  it \"poly arg to typed method param\" do\n    result = ze0(<<~'RUBY')\n      # Sibling to #438. A poly local guarded by `is_a?(String)` passed\n      # as a positional arg to a top-level typed-param method: the call\n      # site unboxes via `(lv_v).v.s` so the const-char* parameter\n      # type-checks. Same shape for Integer / Float narrows.\n\n      def helper_s(s)\n        s.length\n      end\n\n      def encode(v)\n        return helper_s(v) if v.is_a?(String)\n        -1\n      end\n\n      puts encode(\"hello\")\n      puts encode(42)\n\n      def helper_i(i)\n        i * 2\n      end\n\n      def double_if_int(v)\n        return helper_i(v) if v.is_a?(Integer)\n        0\n      end\n\n      puts double_if_int(7)\n      puts double_if_int(\"nope\")\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      5\n      -1\n      14\n      0\n    OUT\n  end\n\n  it \"poly dispatch narrow return type\" do\n    result = ze0(<<~'RUBY')\n      # #549. Followup to #531. The cls_id-switch dispatch's RESULT\n      # temp widened to sp_RbVal even when every reachable arm\n      # returned the same scalar. The reachable set is computed by\n      # the same arm-suppression logic the codegen emit loop applies:\n      # arms whose param types are incompatible with the dispatch\n      # site's arg types are pruned, and only arms in the observed\n      # obj-class set survive. With both filters applied, the return\n      # types of surviving arms are unified; if they agree on a\n      # scalar (e.g. all `const char *`), the result temp uses that\n      # scalar instead of sp_RbVal, and the boxed arm rhs (`_t =\n      # sp_box_str(...)`) collapses to a direct assignment.\n      #\n      # Shape: M::Server#run takes `port:int` and returns int; the\n      # Worker family takes `item:string` and returns string. The\n      # dispatch site `@w.run(item)` supplies a string, so M::Server's\n      # arm is param-incompat and pruned. The Worker arms return\n      # string, so the dispatch produces `const char *` and the\n      # scalar-only consumer `s + \".\"` below compiles correctly.\n      # Pre-fix, the dispatch result was sp_RbVal and `s + \".\"`\n      # routed through sp_poly_concat -- still ran but the\n      # concatenated form leaked the boxing.\n      #\n      # Discriminator: `Holder#use` returns `s + \".\"`. If the\n      # dispatch result is sp_RbVal, `s + \".\"` lowers through\n      # sp_poly_concat, which formats the box and produces e.g.\n      # `x!.` only because sp_box_str / sp_poly_concat happen to\n      # preserve the underlying string. The shape is correct but\n      # the path is wrong; once the dispatch is narrowed to\n      # const char *, `s + \".\"` lowers to sp_str_concat which is\n      # what we want.\n\n      module M\n        class WorkerA\n          def run(item); item + \"!\"; end\n        end\n        class WorkerB\n          def run(item); item + \"?\"; end\n        end\n        class Holder\n          def initialize(w); @w = w; end\n          def use(item)\n            s = @w.run(item)\n            s + \".\"\n          end\n        end\n        class Server\n          def run(port); port + 1; end\n        end\n      end\n\n      puts M::Holder.new(M::WorkerA.new).use(\"x\")\n      puts M::Holder.new(M::WorkerB.new).use(\"y\")\n      puts M::Server.new.run(80)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      x!.\n      y?.\n      81\n    OUT\n  end\n\n  it \"poly local is a string narrow in non tail if\" do\n    _(ze0(<<~'RUBY')).must_answer \"OK\\n\"\n      # Sibling case to poly_local_is_a_string_narrow_in_tail_if (#612):\n      # a poly-typed local narrowed via `if content.is_a?(String) ... end`\n      # when the if is NOT in tail position. Before this fix\n      # compile_if_stmt didn't push the is_a? narrow, so a typed-arg\n      # callee inside the body (sp_re_escape's `const char *`) saw the\n      # raw sp_RbVal and tripped a C compile. The fix mirrors\n      # compile_cond_return's narrow push and also switches\n      # compile_stmt's LV-write to use the slot's declared type so a\n      # rewrite of the narrowed var inside the body picks the slot arm,\n      # not the narrow's pseudo-type. Issue #615.\n\n      class Resp\n        attr_reader :body\n        def initialize(b); @body = b; end\n      end\n\n      class Tester\n        attr_accessor :response\n\n        def assert_select(selector, content_or_opts = nil, &block)\n          body = response.body\n          if content_or_opts.is_a?(Hash)\n            content = nil\n          else\n            content = content_or_opts\n          end\n          if content.is_a?(String)\n            pattern = Regexp.new(\"<\#{selector}>\#{Regexp.escape(content)}<\")\n            raise \"no match\" unless pattern.match?(body)\n          end\n          yield if block\n        end\n      end\n\n      t = Tester.new\n      t.response = Resp.new(\"<h1>Title<\")\n      t.assert_select(\"h1\", \"Title\")\n      t.assert_select(\"div\", { count: 1 })\n      puts \"OK\"\n    RUBY\n  end\n\n  it \"poly local is a string narrow in tail if\" do\n    _(ze0(<<~'RUBY')).must_answer \"match\\n\"\n      # Tail-position `if x.is_a?(C) ... end` now pushes a narrow for `x`\n      # inside the body, so a typed callee that consumes `x` unboxes via\n      # the matching union field (`.v.s` for string, `.v.i` for int, etc.)\n      # instead of emitting the raw sp_RbVal. Issue #612: pre-fix\n      # Regexp.escape on a poly param narrowed via `is_a?(String)` emitted\n      # `sp_re_escape(lv_x)` against the un-narrowed slot and the C\n      # compile failed.\n\n      def matcher(content_or_opts)\n        if content_or_opts.is_a?(Hash)\n          content = nil\n        else\n          content = content_or_opts\n        end\n        if content.is_a?(String)\n          pattern = Regexp.new(\"<h1>\#{Regexp.escape(content)}<\")\n          body = \"<h1>Title<\"\n          puts pattern.match?(body) ? \"match\" : \"no match\"\n        end\n      end\n\n      matcher(\"Title\")\n      matcher({ \"opt\" => 1 })   # content is nil, skips the inner if entirely\n    RUBY\n  end\n\n  it \"poly local is a string narrow in y1 inline\" do\n    _(ze0(<<~'RUBY')).must_answer \"OK\\n\"\n      # Sibling to #615 (poly_local_is_a_string_narrow_in_non_tail_if):\n      # the is_a? narrow + LV-read unbox must also fire inside the y1\n      # inlined specialization that block-passing creates. The\n      # non-inlined `sp_Base_check` body already unboxed correctly after\n      # #615 / #817149f; the inlined y1 copy emitted the raw poly local\n      # where `const char *` is expected. Issue #624.\n\n      class Base\n        def check(content = nil, &block)\n          if content.is_a?(String)\n            pattern = Regexp.new(Regexp.escape(content))\n            raise \"no match\" unless pattern.match?(content)\n          end\n          yield if block\n        end\n      end\n\n      class Sub < Base\n        def run\n          check(\"hello\")\n          check(123)        # makes content's static type poly\n          check { nil }     # block-passing call triggers y1 inlining\n        end\n      end\n\n      Sub.new.run\n      puts \"OK\"\n    RUBY\n  end\n\n  it \"poly recv dispatch narrow module\" do\n    result = ze0(<<~'RUBY')\n      # #531. Sibling to #513. The poly-recv narrowing in af55659\n      # walks the global AST for `<Class>.new(...)` call sites to\n      # recover concrete classes seen at a poly ivar slot. The walker\n      # matched only `ConstantReadNode` receivers, so module-scoped\n      # classes (`module M; class Holder; end; end` with call sites\n      # `M::Holder.new(...)`) fell through to the all-classes fallback.\n      # Server got pulled into M::Holder.use's cls_id-dispatch table\n      # even though no M::Server is ever assigned to @w, and\n      # M::Server#run's port widened to sp_RbVal.\n      #\n      # Fix: also match `ConstantPathNode` receivers via\n      # `const_ref_flat_name`, which produces the same flattened\n      # `Mod_Class` form that `@cls_names` stores.\n\n      module M\n        class WorkerA\n          def run(item); item + \"!\"; end\n        end\n        class WorkerB\n          def run(item); item + \"?\"; end\n        end\n        class Holder\n          def initialize(w); @w = w; end\n          def use(item); @w.run(item); end\n        end\n        # Same shape as #513's top-level Server: same method name (`run`),\n        # different param type (int instead of string). After the fix,\n        # M::Server#run keeps `mrb_int lv_port` and M::Server is dropped\n        # from the M::Holder.use dispatch table.\n        class Server\n          def run(port); port + 1; end\n        end\n      end\n\n      puts M::Holder.new(M::WorkerA.new).use(\"x\")\n      puts M::Holder.new(M::WorkerB.new).use(\"y\")\n      puts M::Server.new.run(80)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      x!\n      y?\n      81\n    OUT\n  end\n\n  it \"poly slot typed array read\" do\n    result = ze0(<<~'RUBY')\n      # A typed array stored into a poly slot -- a Hash value, here -- has a\n      # different layout from the poly array the index read assumed, so every\n      # element came back nil.\n      h = {}\n      h[\"a\"] = [7, 8, 9]\n      row = h[\"a\"]\n      p row[0]\n      p row[2]\n      p row[-1]\n      p row[9]\n\n      h[\"b\"] = [\"x\", \"y\"]\n      p h[\"b\"][1]\n      h[\"c\"] = [1.5, 2.5]\n      p h[\"c\"][0]\n      h[\"d\"] = [1, \"s\"]\n      p h[\"d\"][1]\n\n      # a poly array in the same slot keeps working\n      h[\"e\"] = [1, :two, \"three\"]\n      e = h[\"e\"]\n      p e[0]\n      p e[1]\n      p e[-1]\n\n      # and so does a nested read without the intermediate local\n      p h[\"a\"][1]\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      7\n      9\n      9\n      nil\n      \"y\"\n      1.5\n      \"s\"\n      1\n      :two\n      \"three\"\n      8\n    OUT\n  end\nend\n", "../../spec/compiler/fusion/enumeration_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Fusion: enumeration\" do\n  it \"fused inject carries its accumulator\" do\n    result = ze0(<<~'RUBY')\n      arr = [1, 2, 3, 4]\n\n      p arr.inject(0) { |a, b| a + b }\n      p arr.inject(10) { |a, b| a + b }\n      p arr.reduce([]) { |a, b| a << b }\n      p arr.inject(\"\") { |a, b| a += b.to_s; a }\n\n      # The block's VALUE is the next accumulator, so reassigning either param\n      # inside the body only matters through what the body evaluates to.\n      p arr.inject(0) { |a, b| b = 100; a + b }\n      p(arr.inject(0) { |a, b| next a })\n\n      # An empty receiver never calls the block and answers the seed.\n      p [].inject(:seed) { |a, b| :other }\n\n      # `break` overrides the whole call.\n      p(arr.inject(0) { |a, b| break :early })\n\n      # Without an explicit seed the first element IS the seed and the block is not\n      # called for it -- a different shape, which takes the dynamic row.\n      p arr.inject { |a, b| a + b }\n      p arr.inject(:+)\n\n      # A block with any count other than two params also takes the dynamic row.\n      p arr.inject(0) { |a| 7 }\n\n      # Nested drivers, each with its own accumulator.\n      p arr.inject(0) { |a, b| a + [b, b].inject(0) { |c, d| c + d } }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      10\n      20\n      [1, 2, 3, 4]\n      \"1234\"\n      400\n      0\n      :seed\n      :early\n      10\n      10\n      7\n      20\n    OUT\n  end\n\n  it \"lazy unfused terminal\" do\n    result = ze0(<<~'RUBY')\n      # A terminal the lazy pipeline does not fuse -- sum, count, min, include? --\n      # runs on the materialized result. Without an arm the call answered nil or\n      # refused to compile.\n      p([1, 2, 3].lazy.sum)\n      p([1, 2, 3].lazy.count)\n      p([1, 2, 3].lazy.min)\n      p([1, 2, 3].lazy.max)\n      p([1, 2, 3].lazy.include?(2))\n      p([1, 2, 3].lazy.include?(9))\n      p([1, 2, 3].lazy.minmax)\n      p([1, 2, 3].lazy.sort)\n      p([1, 2, 3].lazy.reduce(:+))\n      p([3, 1, 2].lazy.sort_by { |x| -x })\n      p([1, 2, 3].lazy.map { |x| x * 2 }.sum)\n      p([1, 2, 3].lazy.select { |x| x > 1 }.count)\n\n      # the fused terminals are unchanged\n      p([1, 2, 3].lazy.to_a)\n      p([1, 2, 3].lazy.first(2))\n      p([1, 2, 3].lazy.map { |x| x + 1 }.to_a)\n      p((1..Float::INFINITY).lazy.map { |x| x * 2 }.first(3))\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      6\n      3\n      1\n      3\n      true\n      false\n      [1, 3]\n      [1, 2, 3]\n      6\n      [3, 2, 1]\n      12\n      2\n      [1, 2, 3]\n      [1, 2]\n      [2, 3, 4]\n      [2, 4, 6]\n    OUT\n  end\n\n  it \"map each cons typed\" do\n    result = ze0(<<~'RUBY')\n      # Typed block results through each_cons(n).map and each_cons(n).with_index.map\n      # must collect the real values. Guards the emit_boxed refactor of these\n      # collecting emitters against regressing the typed (non-poly) path.\n      p [1, 2, 3, 4].each_cons(2).map { |a, b| a + b }\n      p [1, 2, 3, 4].each_cons(2).map { |pair| pair.sum }\n      p %w[a b c].each_cons(2).map { |x, y| \"\#{x}\#{y}\" }\n      p [10, 20, 30].each_cons(2).with_index.map { |pair, i| pair.sum + i }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [3, 5, 7]\n      [3, 5, 7]\n      [\"ab\", \"bc\"]\n      [30, 51]\n    OUT\n  end\n\n  it \"map untyped block result\" do\n    result = ze0(<<~'RUBY')\n      # An untyped block result (here a read of an unassigned ivar, which is untyped\n      # and evaluates to nil) collected by map / each_cons must produce nil elements,\n      # never crash or mis-box. Covers the area of the untyped-into-poly-array boxing\n      # fix (the RBS-typed reproducer lives in test/rbs-seed/map_untyped_poly.rb).\n      class Collector\n        def plain(arr);           arr.map { |x| @sink };                          end\n        def cons(arr);            arr.each_cons(2).map { |pair| @sink };          end\n        def cons_with_index(arr); arr.each_cons(2).with_index.map { |p, i| @sink }; end\n      end\n\n      c = Collector.new\n      p c.plain([1, 2, 3])\n      p c.cons([1, 2, 3, 4])\n      p c.cons_with_index([1, 2, 3, 4])\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [nil, nil, nil]\n      [nil, nil, nil]\n      [nil, nil, nil]\n    OUT\n  end\n\n  it \"obj array sort typed\" do\n    result = ze0(<<~'RUBY')\n      # No-block sort/sort!/min/max over arrays of user objects. A local touched\n      # only by modeled ops narrows to the typed object-array representation (the\n      # runtime compares through the cmp hook); a component whose sort result\n      # escapes into an unmodeled consumer stays on the boxed poly path -- the\n      # behavior is identical either way. A class without <=> raises like CRuby.\n      class Money\n        include Comparable\n        attr_reader :cents\n        def initialize(cents); @cents = cents; end\n        def <=>(other); cents <=> other.cents; end\n      end\n\n      # narrowed: only admitted ops touch this local and its sort alias\n      bag = [Money.new(30), Money.new(10), Money.new(20)]\n      sorted = bag.sort\n      p sorted.first.cents\n      p sorted.last.cents\n      p bag.min.cents\n      p bag.max.cents\n      p bag.first.cents        # sort is a copy; the receiver is unchanged\n      bag.sort!\n      p bag.first.cents        # sort! reorders in place\n\n      # escaping consumer: the component stays poly (boxed hook path)\n      esc = [Money.new(3), Money.new(1), Money.new(2)]\n      p esc.sort.length\n\n      # empty array: min/max are nil\n      none = [Money.new(1)]\n      none.sort!\n      p none.min.nil?\n\n      # equal-comparing elements: tied elements land in the order of the C\n      # library's qsort_r, as CRuby's do\n      class Card\n        include Comparable\n        attr_reader :rank, :tag\n        def initialize(rank, tag); @rank = rank; @tag = tag; end\n        def <=>(other); rank <=> other.rank; end\n      end\n      deck = [Card.new(1, 0), Card.new(0, 1), Card.new(1, 2), Card.new(0, 3), Card.new(1, 4)]\n      ordered = deck.sort\n      p ordered.map(&:tag)\n\n      # a class without <=> cannot compare, matching CRuby's error\n      class NoCmp\n        attr_reader :v\n        def initialize(v); @v = v; end\n      end\n      plain = [NoCmp.new(2), NoCmp.new(1)]\n      begin\n        plain.sort\n        puts \"no raise\"\n      rescue ArgumentError => e\n        puts e.message\n      end\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      10\n      30\n      10\n      30\n      30\n      10\n      3\n      false\n      [1, 3, 0, 2, 4]\n      comparison of NoCmp with NoCmp failed\n    OUT\n  end\n\n  it \"redefined array each beats the splice\" do\n    _(ze0(<<~'RUBY')).must_answer \"\\\"REDEFINED\\\"\\n\"\n      # A reopen of `Array#each` makes the splice illegal: `iter_inline_ok_for`\n      # answers false and the site's other arm -- an ordinary block send -- is\n      # what finds the new definition. Without that guard a fused site would\n      # keep walking the array and never call the method at all.\n      class Array\n        def each(&b) = \"REDEFINED\"\n      end\n      a = [1, 2, 3]\n      p a.each { |x| x }\n    RUBY\n  end\n\n  it \"two spliced loops in one scope each own their local\" do\n    result = ze0(<<~'RUBY')\n      # Both loops splice into the enclosing scope and both first-assign `r`, so\n      # each gets storage of its own for its loop's extent. The two storages are\n      # registered under synthetic keys, and a key collision left the first loop's\n      # value with no release -- visible only under `ZEO_RT_LEAKCHECK`, which the\n      # memcheck leg runs over every golden.\n      1.times do |i|\n        r = \"a\" + i.to_s\n        p r\n      end\n      1.times do\n        r = \"c\" + \"d\"\n        p r\n      end\n\n      # The same pair with the parameter on the second loop instead.\n      2.times do\n        s = \"e\" * 2\n        p s\n      end\n      2.times do |i|\n        s = \"f\" * i\n        p s\n      end\n\n      # ...and with an accumulating kind between them, whose accumulator slot takes\n      # a synthetic key from the same counter.\n      p (1..3).map { |i| \"m\#{i}\" }\n      1.times do |i|\n        r = \"g\" + i.to_s\n        p r\n      end\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      \"a0\"\n      \"cd\"\n      \"ee\"\n      \"ee\"\n      \"\"\n      \"f\"\n      [\"m1\", \"m2\", \"m3\"]\n      \"g0\"\n    OUT\n  end\n\n  it \"typed array each fuses under a guard\" do\n    result = ze0(<<~'RUBY')\n      # `arr.each { }` on a statically-`Array` receiver splices the block body\n      # into a native loop. Unlike the literal `n.times` shape, the receiver's\n      # class here is a compile-time BELIEF, so the site asks TWO runtime\n      # questions before it may splice, and either can say no:\n      #\n      #   - is the value really an Array (a local analyze typed as one can hold\n      #     anything by the time the loop runs)\n      #   - may a splice stand in for `Array#each` (a reopen, a per-object\n      #     singleton, or a box makes real dispatch the only correct answer)\n      #\n      # with an ordinary block send on the other arm. Everything below has to\n      # behave the same whichever arm runs, which is what this file checks.\n      a = [1,2,3]\n      r = a.each { |x| print x }\n      puts\n      p r.equal?(a)\n      # break, next, redo-free control\n      p(a.each { |x| break x * 10 if x == 2 })\n      s = 0\n      a.each { |x| next if x == 2; s += x }\n      p s\n      # growth while walking: CRuby re-reads the length\n      b = [1]\n      n = 0\n      b.each { |x| n += 1; b << x + 1 if b.size < 4 }\n      p [b, n]\n      # a block that escapes captures a fresh binding per iteration\n      procs = []\n      a.each { |x| procs << -> { x } }\n      p procs.map(&:call)\n      # an empty array\n      p([].each { |x| raise \"never\" })\n      # NOT an array at run time, though analyze may believe otherwise\n      c = [1,2]\n      c = \"ab\" if ARGV[0]\n      p c.each { |x| x }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      123\n      true\n      20\n      4\n      [[1, 2, 3, 4], 4]\n      [1, 2, 3]\n      []\n      [1, 2]\n    OUT\n  end\n\n  it \"user redefinition unfuses the new iterator kinds\" do\n    result = ze0(<<~'RUBY')\n      class Array\n        def detect\n          :from_the_reopen\n        end\n\n        def reduce(seed)\n          :also_from_the_reopen\n        end\n      end\n\n      arr = [1, 2, 3]\n\n      # An alias and its twin are separate method entries, so redefining either one\n      # takes the whole kind off the fused path.\n      p arr.find { |x| x > 1 }\n      p arr.detect { |x| x > 1 }\n      p arr.inject(0) { |a, b| a + b }\n      p arr.reduce(0) { |a, b| a + b }\n\n      # The kinds nobody touched still answer normally.\n      p arr.count { |x| x > 1 }\n      p arr.none? { |x| x > 9 }\n      p arr.all? { |x| x > 0 }\n      p arr.any? { |x| x > 2 }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      2\n      :from_the_reopen\n      6\n      :also_from_the_reopen\n      2\n      true\n      true\n      true\n    OUT\n  end\nend\n", "../../spec/compiler/fusion/formatting_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Fusion: formatting and inspection\" do\n  it \"inlined accessor ignores a later redefinition\" do\n    result = ze0(<<~'RUBY')\n      # A call to an accessor from INSIDE the class was inlined to the ivar read,\n      # and a later `define_method` of that name did not reach it. The same call\n      # from outside saw the redefinition, so one object answered two different\n      # values for one method depending on who asked.\n      #\n      # `inline_accessor` devirtualizes a self-call whose target\n      # `accessor_shape` recognizes: `attr_reader :v`, `attr_writer`, and a `Struct`\n      # member. The fold now asks `zeo_rt_is_live` first and takes the ordinary\n      # dispatch once anything has been defined at run time.\n      #\n      # The guard is emitted only for a name `may_be_patched_at_runtime` answers\n      # for, so a program that redefines nothing emits what it emitted before --\n      # which is what keeps `bm_getivar`/`bm_setivar`/`bm_attr_accessor` unchanged.\n      # The writer half stands down instead of guarding: both arms would lower the\n      # argument from the same node.\n      #\n      # rspec's summary line is the case that found it. The golden stubs\n      # `SummaryNotification#duration` with `define_method(:duration) { 0.0 }`; the\n      # stub worked from outside and the formatter's own `format_duration(duration)`\n      # still read the member.\n\n      class K\n        attr_reader :v\n        def initialize = @v = 1\n        def inside = v\n      end\n\n      k = K.new\n      p k.inside\n      K.class_eval { define_method(:v) { 99 } }\n      p k.inside\n      p k.v\n\n      S = Struct.new(:duration)\n      class S\n        def report = \"took \#{duration}\"\n      end\n      s = S.new(1.5)\n      p s.report\n      S.class_eval { define_method(:duration) { 0.0 } }\n      p s.report\n      p s.duration\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      1\n      99\n      99\n      \"took 1.5\"\n      \"took 0.0\"\n      0.0\n    OUT\n  end\n\n  it \"inlined method celled local\" do\n    result = ze0(<<~'RUBY')\n      # A method local captured by a block is reached through a heap cell. When the\n      # method is INLINED at its call site -- which a `yield` in it forces -- the\n      # inlined body kept the cell form while the prologue declared a plain renamed\n      # local, and nothing declared the cell (#4088). Two halves: the cell form did\n      # not go through the rename map that the plain form did, and the three inline\n      # emitters each declared the plain form for a celled local.\n      #\n      # Same symptom as #4087 from the other side: there the block became a function\n      # of its own, here the callee is folded into the caller.\n\n      # ...and once it built, the repro answered 0 where CRuby answers 7: an inlined\n      # `each` over a poly receiver walks it AS A CONTAINER, and a user class that\n      # defines #each without #to_a -- the ordinary way to write one, forwarding the\n      # block -- walked as an empty array. emit_poly_iter_obj_normalize drives such a\n      # class's own #each with a collector now, which is what it already did for a\n      # class that answers #to_a.\n\n      class Bag\n        def initialize(a) = @a = a\n        def each(&b) = @a.each(&b)\n      end\n\n      class Yielder\n        def initialize(a) = @a = a\n        def each\n          @a.each { |x| yield x }\n        end\n      end\n\n      class WithToA\n        def initialize(a) = @a = a\n        def to_a = @a\n        def each(&b) = @a.each(&b)\n      end\n\n      module M\n        def self.sum_of(list)\n          n = 0\n          list.each { |x| n += yield x }\n          n\n        end\n      end\n\n      def run(list) = M.sum_of(list) { |x| x }\n      puts run([1, 2])\n      puts run([3, 4, 5])\n\n      # the cell types that are not sp_int\n      module F\n        def self.join_of(list)\n          s = \"\"\n          list.each { |x| s += (yield x).to_s }\n          s\n        end\n\n        def self.total_of(list)\n          f = 0.0\n          list.each { |x| f += (yield x) }\n          f\n        end\n\n        def self.gather(list)\n          a = []\n          list.each { |x| a.push(yield x) }\n          a\n        end\n      end\n\n      def joined(list) = F.join_of(list) { |x| x }\n      def totalled(list) = F.total_of(list) { |x| x * 1.0 }\n      def gathered(list) = F.gather(list) { |x| x }\n      p joined([1, 2])\n      p totalled([1, 2])\n      p gathered([1, 2])\n\n      # a closure over the celled local outlives the loop\n      module K\n        def self.keep(list)\n          seen = []\n          list.each { |x| seen.push(yield x) }\n          seen.length\n        end\n      end\n      def kept(list) = K.keep(list) { |x| x }\n      p kept([1, 2, 3])\n\n      p run(Bag.new([3, 4]))\n      p run(Yielder.new([5, 6]))\n      p run(WithToA.new([7, 8]))\n      p kept(Bag.new([1, 2, 3]))\n\n      # not inlined, which has always worked: the same answers\n      def walk(list)\n        t = 0\n        list.each { |x| t += x }\n        t\n      end\n      p walk([1, 2])\n      p walk(Bag.new([3, 4]))\n      p walk(Yielder.new([5, 6]))\n\n      # a class with no each at all still walks as a container where it is one\n      p run([9])\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      3\n      12\n      \"12\"\n      3.0\n      [1, 2]\n      3\n      7\n      11\n      15\n      3\n      3\n      7\n      11\n      9\n    OUT\n  end\n\n  it \"instance exec spliced types\" do\n    result = ze0(<<~'RUBY')\n      # String, symbol, and mixed-type block params inside a spliced\n      # trampoline body.\n      #\n      # The trampoline-pattern inliner splices the block body at the\n      # call site with each block param bound to a per-call-site C\n      # local (e.g. `s_ix1` instead of `s`). For `puts <s>` and similar\n      # type-aware dispatch inside the spliced body to format the\n      # value correctly, the analyzer must resolve `s`'s type to\n      # \"string\" via find_var_type. Previously only the suffixed name\n      # (`s_ix1`) was declared in the splice scope, so find_var_type\n      # of the original `s` returned \"\" and puts defaulted to integer\n      # format -- string params printed as garbage ints.\n      #\n      # Now the splice declares each block param under both names\n      # (`s_ix1` AND `s`), and the splice scope is bracketed by\n      # push_scope / pop_scope so the original-name declaration shadows\n      # outer locals only inside the splice. Outer locals with the\n      # same name (e.g. an outer `b = Builder.new` and a block param\n      # `|b|`) are restored after the splice via pop_scope.\n      #\n      # Tag has a subclass (TagPlus) so Spinel keeps it heap-allocated\n      # (multi-instance classes can't be SRA-promoted to value types).\n\n      class Tag\n        def fire(s, y, n, &b)\n          instance_exec(s, y, n, &b)\n        end\n      end\n\n      class TagPlus < Tag\n      end\n\n      t = Tag.new\n      t.fire(\"hi\", :sym, 7) { |s, y, n| puts s; puts y; puts n }\n\n      # Block-param name shadowing an outer local: `b` (the receiver)\n      # vs `|b|` (the second block param). After the splice, `b` must\n      # still be the Builder so subsequent dispatch works.\n      class Builder\n        def initialize; @s = 0; end\n        def add(n); @s = @s + n; end\n        def total; @s; end\n      end\n\n      class BuilderPlus < Builder\n      end\n\n      b = Builder.new\n      t.fire(\"hi\", :sym, 7) { |s, y, n| b.add(n) }   # `b` here is the outer Builder\n      t.fire(\"hi\", :sym, 7) { |s, y, n| b.add(n) }\n\n      # Now actually shadow `b`: the middle block param is named `b`, so inside\n      # the splice `b` is the :sym param (prints \"sym\"), not the Builder. After\n      # the splice pop_scope restores `b`, so puts b.total below still sees the\n      # Builder. If the restore were missing, `b.total` would mis-resolve.\n      t.fire(\"hi\", :sym, 7) { |s, b, n| puts b }\n      puts b.total                     # 14\n\n      puts \"done\"\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      hi\n      sym\n      7\n      sym\n      14\n      done\n    OUT\n  end\n\n  it \"matchdata methods work on a dynamically typed receiver\" do\n    result = ze0(<<~'RUBY')\n      # `$~` can be nil (whenever the last match failed), so it never infers\n      # as `TyKind::MatchData` and can't take codegen's static MatchData fast\n      # path -- it dispatches dynamically, which needs a real runtime table.\n      # `$~[0]` raised NoMethodError while `re.match(s)[0]` worked.\n\n      \"hello\" =~ /e(l+)(o)/\n      m = $~\n      p m[0]\n      p m[1]\n      p m.captures\n      p m.pre_match\n      p m.post_match\n      p m.to_a\n      p m.string\n      p m.to_s\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      \"ello\"\n      \"ll\"\n      [\"ll\", \"o\"]\n      \"h\"\n      \"\"\n      [\"ello\", \"ll\", \"o\"]\n      \"hello\"\n      \"ello\"\n    OUT\n  end\n\n  it \"typed array empty returns nil\" do\n    result = ze0(<<~'RUBY')\n      # Issue #832: int_array pop/shift/min/max on empty return nil\n      # (int? sentinel SP_INT_NIL) per MRI. Non-empty returns the value.\n      # float_array is deferred (needs float? sentinel design).\n      a = [1, 2]\n      2.times { a.pop }\n      puts \"empty int pop: \" + a.pop.inspect\n\n      b = [1, 2]\n      2.times { b.shift }\n      puts \"empty int shift: \" + b.shift.inspect\n\n      puts \"empty int min: \" + [].min.inspect\n      puts \"empty int max: \" + [].max.inspect\n\n      # Non-empty still works.\n      puts [1, 2, 3].pop\n      puts [1, 2, 3].shift\n      puts [3, 1, 2].min\n      puts [3, 1, 2].max\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      empty int pop: nil\n      empty int shift: nil\n      empty int min: nil\n      empty int max: nil\n      3\n      1\n      1\n      3\n    OUT\n  end\n\n  it \"typed hash caller no body widen\" do\n    _(ze0(<<~'RUBY')).must_answer \"alice/5/<i>I</i>\\n\"\n      # #556 (Ori Pekelman). Smoke test for the move of\n      # infer_hash_param_from_body out of the iterative inference\n      # loop. The full bug only triggers in tep's framework\n      # surface (where iter 0 leaves the param's ivar slot\n      # untyped, the body-usage widening fires, then\n      # unify_call_types pulls it to poly against the actual\n      # typed caller). Reductions to a standalone script don't\n      # reproduce -- iter 0 already pins the ivar via the\n      # initial-literal observation. Documenting both here:\n      # this fixture exercises the \"typed caller + body[]\n      # usage\" shape end-to-end so a future regression that\n      # poisons the typed-caller path would be caught even if\n      # the iter-0 timing is more permissive than tep's.\n      #\n      # Verified against tep@9ca09fd: pre-fix\n      # `sp_tep_mustache_m_ivars(sp_StrStrHash *, sp_RbVal)`,\n      # post-fix `sp_tep_mustache_m_ivars(sp_StrStrHash *, sp_StrStrHash *)`,\n      # caller drops the sp_box_obj wrap.\n\n      class Request\n        attr_accessor :ivars\n        def initialize\n          @ivars = {\"k\" => \"v\"}\n          @ivars.delete(\"k\")\n        end\n      end\n\n      def lookup_typed(h, key)\n        h[key].to_s\n      end\n\n      def forward_to_typed(locals, ivars)\n        out = \"\"\n        out += lookup_typed(ivars, \"name\")\n        out += \"/\"\n        out += lookup_typed(ivars, \"count\")\n        out += \"/\"\n        out += ivars[\"raw\"].to_s\n        out\n      end\n\n      req = Request.new\n      req.ivars[\"name\"] = \"alice\"\n      req.ivars[\"count\"] = \"5\"\n      req.ivars[\"raw\"] = \"<i>I</i>\"\n      puts forward_to_typed({\"unused\" => \"x\"}, req.ivars)\n    RUBY\n  end\n\n  it \"typed hash inspect and each value\" do\n    result = ze0(<<~'RUBY')\n      # Issue #851: typed-hash inspect for sym_int_hash, plus\n      # Hash#each_value across common typed hashes.\n      h = {a: 1, b: 2}\n      puts h.inspect\n      h.each_value { |v| puts v * 10 }\n\n      # str_int_hash.\n      counts = {\"x\" => 5, \"y\" => 7}\n      counts.each_value { |v| puts v + 1 }\n\n      # inspect on str_int_hash.\n      puts counts.inspect\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      {a: 1, b: 2}\n      10\n      20\n      6\n      8\n      {\"x\" => 5, \"y\" => 7}\n    OUT\n  end\n\n  it \"typed hash missing returns nil\" do\n    result = ze0(<<~'RUBY')\n      # Issue #833 (#801 partial): *StrHash missing-key bracket access\n      # returns nil per MRI, not the type's zero value.\n      # *IntHash variants still return 0 (their analyze-side LV slot\n      # can't be widened to int? without cascading through declare_var --\n      # deferred to a follow-up phase).\n\n      # SymStrHash\n      puts({a: \"hi\"}[:missing].inspect)\n\n      # StrStrHash\n      puts({\"a\" => \"hi\"}[\"missing\"].inspect)\n\n      # IntStrHash\n      puts({1 => \"hi\"}[99].inspect)\n\n      # Existing key still works\n      puts({a: \"hello\"}[:a])\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      nil\n      nil\n      nil\n      hello\n    OUT\n  end\nend\n", "../../spec/compiler/fusion/fusion_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Fusion programs\" do\n  it \"array flatten typed elements\" do\n    result = ze0(<<~'RUBY')\n      # Array#flatten on a typed-array-of-typed-array concatenates the inner\n      # arrays into one flat typed array. Previously only int elements were\n      # specialized; str and float now mirror it (the pr_geohash gem's\n      # neighbors does map{...}.flatten over string cells).\n      ints = [[1, 2], [3, 4]]\n      p ints.flatten\n      puts ints.flatten.length\n\n      strs = [[\"a\", \"b\"], [\"c\", \"d\"]]\n      p strs.flatten\n      puts strs.flatten.length\n\n      floats = [[1.0, 2.0], [3.5, 4.5]]\n      p floats.flatten\n      puts floats.flatten.length\n\n      # Uneven inner lengths and an empty inner array.\n      mixed = [[\"x\"], [], [\"y\", \"z\"]]\n      p mixed.flatten\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [1, 2, 3, 4]\n      4\n      [\"a\", \"b\", \"c\", \"d\"]\n      4\n      [1.0, 2.0, 3.5, 4.5]\n      4\n      [\"x\", \"y\", \"z\"]\n    OUT\n  end\n\n  it \"array splice exceptions\" do\n    result = ze0(<<~'RUBY')\n      # Array#[]= splice exceptional cases: exact CRuby exception class + message.\n\n      # negative length raises IndexError\n      begin\n        a = [1, 2, 3, 4]\n        a[1, -2] = [9]\n      rescue IndexError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # negative length via the start,len scalar form too\n      begin\n        a = [1, 2, 3]\n        a[0, -1] = 5\n      rescue IndexError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # splicing into a frozen array raises FrozenError\n      begin\n        a = [1, 2, 3].freeze\n        a[0, 1] = [9]\n      rescue FrozenError => e\n        puts e.class\n      end\n\n      # a start before the front raises IndexError\n      begin\n        a = [1, 2, 3]\n        a[-9, 1] = [0]\n      rescue IndexError => e\n        puts e.class\n      end\n\n      # poly receiver (an element that is a typed array at runtime): same exceptions.\n      # negative length\n      begin\n        a = [[1, 2, 3], \"x\"]\n        a[0][1, -1] = [9]\n      rescue IndexError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # start before the front\n      begin\n        a = [[1, 2, 3], \"x\"]\n        a[0][-5, 1] = [9]\n      rescue IndexError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # a range whose begin is before the front raises RangeError (not IndexError)\n      begin\n        a = [[1, 2, 3], \"x\"]\n        a[0][-10..1] = [9]\n      rescue RangeError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # an endless range whose begin is before the front raises RangeError too\n      begin\n        a = [[1, 2, 3], \"x\"]\n        a[0][-10..] = [9]\n      rescue RangeError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # promoting a frozen typed array still raises FrozenError\n      begin\n        a = [[1, 2, 3].freeze, \"x\"]\n        a[0][1, 1] = [\"s\"]\n      rescue FrozenError => e\n        puts e.class\n      end\n\n      # check ORDER matches CRuby: frozen wins over negative length...\n      begin\n        a = [1, 2, 3].freeze\n        a[1, -1] = [9]\n      rescue => e\n        puts e.class\n      end\n\n      # ...over a too-small index...\n      begin\n        a = [1, 2, 3].freeze\n        a[-9, 1] = [9]\n      rescue => e\n        puts e.class\n      end\n\n      # ...and over an out-of-range range (typed receiver)\n      begin\n        a = [1, 2, 3].freeze\n        a[-9..0] = [1]\n      rescue => e\n        puts e.class\n      end\n\n      # the same order through the poly runtime path\n      begin\n        a = [[1, 2, 3].freeze, \"x\"]\n        a[0][1, -1] = [9]\n      rescue => e\n        puts e.class\n      end\n      begin\n        a = [[1, 2, 3].freeze, \"x\"]\n        a[0][-10..1] = [9]\n      rescue => e\n        puts e.class\n      end\n\n      # negative length is reported before a too-small index (CRuby checks length first)\n      begin\n        a = [1, 2, 3]\n        a[-9, -1] = [5]\n      rescue IndexError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n      begin\n        y = [1, \"x\"]\n        y[-9, -1] = [5]\n      rescue IndexError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # a range beginning before -len raises RangeError on a typed receiver too\n      begin\n        a = [1, 2, 3]\n        a[-9..0] = [1]\n      rescue RangeError => e\n        puts \"\#{e.class}: \#{e.message}\"\n      end\n\n      # typed receivers handle beginless / endless range splices\n      b = [1, 2, 3]\n      b[..1] = [9]\n      p b\n      b = [1, 2, 3]\n      b[1..] = [8]\n      p b\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      IndexError: negative length (-2)\n      IndexError: negative length (-1)\n      FrozenError\n      IndexError\n      IndexError: negative length (-1)\n      IndexError: index -5 too small for array; minimum: -3\n      RangeError: -10..1 out of range\n      RangeError: -10.. out of range\n      FrozenError\n      FrozenError\n      FrozenError\n      FrozenError\n      FrozenError\n      FrozenError\n      IndexError: negative length (-1)\n      IndexError: negative length (-1)\n      RangeError: -9..0 out of range\n      [9, 3]\n      [1, 8]\n    OUT\n  end\n\n  it \"array splice kinds\" do\n    result = ze0(<<~'RUBY')\n      # Array#[start, len] = replacement across element kinds: the equal-length\n      # overwrite (the fast path) and the growing / shrinking / clamped forms.\n      a = [1, 2, 3, 4, 5]\n      a[1, 3] = [9, 9, 9]\n      p a\n      a[0, 2] = [7]\n      p a\n      a[2, 0] = [5, 5]\n      p a\n      b = [\"x\", \"y\", \"z\"]\n      b[1, 2] = [\"p\", \"q\"]\n      p b\n      c = [1.5, 2.5, 3.5]\n      c[0, 2] = [9.5, 8.5]\n      p c\n      d = [1, \"a\", :b]\n      d[1, 1] = [\"z\"]\n      p d\n      e = [1, 2, 3]\n      e[1, 5] = [8]\n      p e\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [1, 9, 9, 9, 5]\n      [7, 9, 9, 5]\n      [7, 9, 5, 5, 9, 5]\n      [\"x\", \"p\", \"q\"]\n      [9.5, 8.5, 3.5]\n      [1, \"z\", :b]\n      [1, 8]\n    OUT\n  end\n\n  it \"array splice to ary\" do\n    result = ze0(<<~'RUBY')\n      # A splice RHS that defines to_ary is coerced through it (CRuby rb_ary_to_ary):\n      # the coercion's elements are spliced, while the expression value stays the\n      # object as written. An object without to_ary inserts as a single element.\n      class IntPair\n        def initialize(a, b); @a = a; @b = b; end\n        def to_ary; [@a, @b]; end\n      end\n\n      class Tagged\n        def initialize(v); @v = v; end\n        def to_ary; [\"<\", @v, \">\"]; end\n      end\n\n      class Opaque\n        def initialize(v); @v = v; end\n      end\n\n      # typed receiver, to_ary elements match the element kind: stays typed\n      a = [1, 2, 3]\n      a[1, 1] = IntPair.new(7, 8)\n      p a\n\n      # range form\n      b = [1, 2, 3, 4]\n      b[1..2] = IntPair.new(9, 9)\n      p b\n\n      # mixed to_ary elements widen the receiver, then splice faithfully\n      c = [1, 2, 3]\n      c[1, 1] = Tagged.new(5)\n      p c\n\n      # an object without to_ary inserts as one element (widening the receiver)\n      d = [1, 2, 3]\n      d[0, 2] = Opaque.new(1)\n      p d.length\n      p d[1]\n\n      # a poly receiver (array element that is an array at runtime) coerces too\n      e = [[1, 2, 3], \"x\"]\n      e[0][1, 1] = IntPair.new(4, 5)\n      p e[0]\n\n      # value position: the expression value is the object itself, not the coercion\n      f = [1, 2, 3]\n      r = (f[1, 1] = IntPair.new(6, 6))\n      p r.is_a?(IntPair)\n      p f\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [1, 7, 8, 3]\n      [1, 9, 9, 4]\n      [1, \"<\", 5, \">\", 3]\n      2\n      3\n      [1, 4, 5, 3]\n      true\n      [1, 6, 6, 3]\n    OUT\n  end\n\n  it \"array transpose typed elements\" do\n    result = ze0(<<~'RUBY')\n      # Array#transpose on a nested array swaps rows and columns. Previously\n      # only int elements were specialized; str and float now mirror it\n      # (pr_geohash's GeoHash.decode ends with latlng.transpose over floats).\n      ints = [[1, 2, 3], [4, 5, 6]]\n      p ints.transpose\n\n      floats = [[1.0, 2.0], [3.0, 4.0]]\n      p floats.transpose\n      puts floats.transpose[0][0]\n      puts floats.transpose[1][1]\n\n      strs = [[\"a\", \"b\"], [\"c\", \"d\"]]\n      p strs.transpose\n\n      # Square and single-row matrices.\n      sq = [[1, 2], [3, 4]]\n      p sq.transpose\n      one = [[\"x\", \"y\", \"z\"]]\n      p one.transpose\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [[1, 4], [2, 5], [3, 6]]\n      [[1.0, 3.0], [2.0, 4.0]]\n      1.0\n      4.0\n      [[\"a\", \"c\"], [\"b\", \"d\"]]\n      [[1, 3], [2, 4]]\n      [[\"x\"], [\"y\"], [\"z\"]]\n    OUT\n  end\n\n  it \"autoload nested in a module eagerly splices the feature file\" do\n    _(ze0(<<~'RUBY', files: {\"autoload_nested_in_a_module_eagerly_splices_the_feature_file/lib/greeter.rb\" => \"module App\\n  module Greeter\\n    def self.hi(n); \\\"hi \\\#{n}\\\"; end\\n  end\\nend\\n\", \"autoload_nested_in_a_module_eagerly_splices_the_feature_file/main.rb\" => \"module App\\n  autoload :Greeter, \\\"greeter\\\"\\nend\\nputs App::Greeter.hi(\\\"bob\\\")\\n\"})).must_answer \"hi bob\\n\"\n      # #101: `autoload :Const, \"feature\"` is treated as a compile-time\n      # require -- the loader's eager pre-pass splices the feature file (at any\n      # structural nesting) so the constant is defined; the `autoload` call\n      # itself is a no-op. Documented divergence from CRuby's laziness (loads at\n      # the autoload site, not first access), but observationally identical for\n      # a definitional autoloaded file.\n\n      $LOAD_PATH.unshift(File.expand_path(\"autoload_nested_in_a_module_eagerly_splices_the_feature_file/lib\", __dir__))\n      require_relative \"autoload_nested_in_a_module_eagerly_splices_the_feature_file/main\"\n    RUBY\n  end\n\n  it \"case in class check pattern binds and statically narrows to int\" do\n    _(ze0(<<~'RUBY')).must_answer \"6\\n\"\n      # `Integer => n` both binds `n` AND statically narrows its type for the\n      # rest of the arm's body -- `n + 1` should take the native `Int`\n      # arithmetic fast path, not a runtime Poly fallback.\n\n      case 5\n      in Integer => n\n        puts n + 1\n      end\n    RUBY\n  end\n\n  it \"case in nested array pattern narrows each element\" do\n    _(ze0(<<~'RUBY')).must_answer \"1a 2b\\n\"\n      case [[1, \"a\"], [2, \"b\"]]\n      in [[Integer => n1, String => s1], [Integer => n2, String => s2]]\n        puts \"\#{n1}\#{s1} \#{n2}\#{s2}\"\n      end\n    RUBY\n  end\n\n  it \"cls method specialization boxer\" do\n    result = ze0(<<~'RUBY')\n      class Base\n        def self.from_row(row)\n          instance = new\n          if row.is_a?(CommentRow)\n            instance.commenter = row.commenter\n          elsif row.is_a?(ArticleRow)\n            instance.title = row.title\n          end\n          instance\n        end\n\n        def []=(field, value)\n          case field\n          when :commenter then @commenter = value\n          when :title then @title = value\n          when :body then @body = value\n          end\n        end\n      end\n\n      class Comment < Base\n        attr_accessor :commenter\n        attr_accessor :body\n      end\n\n      class Article < Base\n        attr_accessor :title\n      end\n\n      class CommentRow\n        attr_reader :commenter\n        def initialize(c); @commenter = c; end\n      end\n\n      class ArticleRow\n        attr_reader :title\n        def initialize(t); @title = t; end\n      end\n\n      seed = Comment.new\n      seed[:body] = 42\n      seed[:commenter] = \"x\"\n\n      c = Comment.from_row(CommentRow.new(\"alice\"))\n      a = Article.from_row(ArticleRow.new(\"title!\"))\n      puts c.commenter\n      puts a.title\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      alice\n      title!\n    OUT\n  end\n\n  it \"cmethod transitive specialization\" do\n    result = ze0(<<~'RUBY')\n      # A class method called on a subclass must specialize through a non-overriding\n      # intermediate, so an implicit-self chain reaching an override resolves to the\n      # subclass version, not the abstract base (#1451).\n      class Base\n        def self.table_name\n          raise \"\#{name}.table_name must be overridden\"\n        end\n        def self.adapter_all\n          \"[\" + table_name + \"]\"\n        end\n        def self.all\n          adapter_all          # transitive: all -> adapter_all -> table_name\n        end\n        def self.last\n          \"last-of-\" + all     # one more hop\n        end\n      end\n      class Article < Base\n        def self.table_name; \"articles\"; end\n      end\n      class User < Base\n        def self.table_name; \"users\"; end\n      end\n      puts Article.last\n      puts User.last\n      puts Article.all\n      puts User.adapter_all\n\n      # the direct (1-hop) case must keep working\n      class B2\n        def self.label;    raise \"abstract\"; end\n        def self.describe; label; end\n      end\n      class S2 < B2\n        def self.label; \"s2-label\"; end\n      end\n      puts S2.describe\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      last-of-[articles]\n      last-of-[users]\n      [articles]\n      [users]\n      s2-label\n    OUT\n  end\n\n  it \"const recv yield inline\" do\n    _(ze0(<<~'RUBY')).must_answer \"1 2 3 \\n6\\n1 2 3 4 \\n\"\n      # A yield-based method called with a block on a constant receiver. The constant\n      # holds an instance (not a class name), so the inline path must fall through to\n      # instance-method lookup rather than treating it as a class method -- otherwise\n      # the call referenced an unemitted function and failed to link.\n      class Bag\n        def initialize(a)\n          @a = a\n        end\n        def each\n          @a.each { |x| yield x }\n        end\n        def sum_each\n          s = 0\n          @a.each { |x| s += x }\n          s\n        end\n      end\n\n      NUMS = Bag.new([1, 2, 3])\n      NUMS.each { |x| print x, \" \" }\n      puts\n      p NUMS.sum_each        # 6\n\n      PAIRS = Bag.new([[1, 2], [3, 4]])\n      PAIRS.each do |pair|\n        pair.each { |y| print y, \" \" }\n      end\n      puts\n    RUBY\n  end\n\n  it \"container fast path argument may reassign its receiver\" do\n    result = ze0(<<~'RUBY')\n      # The container fast paths (`a << x`, `a[i] = v`, `h[k] = v`, `a.length`,\n      # `a.pop`, `h[k]`) BORROW a plain hoisted receiver instead of cloning it --\n      # but the borrow is live while the arguments evaluate, and an argument that\n      # reassigns the receiver's own local is perfectly good Ruby. Each line below\n      # does exactly that, and each must answer what CRuby answers rather than\n      # failing to compile with E0506.\n      a = [1]\n      a << (a = [9]; 2)\n      p a\n      b = [1, 2]\n      b[0] = (b = [7, 8]; 5)\n      p b\n      h = { x: 1 }\n      h[:y] = (h = { z: 3 }; 4)\n      p h\n      c = [1, 2, 3]\n      p c.length + (c = []; 0)\n      d = [5]\n      p d[(d = [6, 7]; 0)]\n      e = [1]\n      p e.pop + (e = [2]; 0)\n      f = { a: 1 }\n      p f[(f = { b: 2 }; :a)].inspect\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [9]\n      [7, 8]\n      {z: 3}\n      3\n      5\n      1\n      \"1\"\n    OUT\n  end\n\n  it \"data define inline receiver\" do\n    result = ze0(<<~'RUBY')\n      a = Data.define(:x, :y).new(1, 2)\n      p a\n      p a.x\n      p a.y\n      p(Data.define(:x, :y).class)\n      p(Data.define(:x, :y).members)\n      b = Struct.new(:a, :b).new(3, 4)\n      p b.a\n      p b.b\n      p(Struct.new(:m, :n).members)\n      # named form still works\n      Pt = Data.define(:lat, :lng)\n      p Pt.new(10, 20)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      #<data x=1, y=2>\n    