     end\n      p flt(2.5)                  #=> 3.5\n      p flt(\"z\")                  #=> \"z\"\n\n      # 5. Array narrowing works across element representations.\n      def sa(v)\n        v.is_a?(Array) ? v.first : nil\n      end\n      p sa([\"a\", \"b\"])            #=> \"a\"\n      p sa([1.5, 2.5])            #=> 1.5\n\n      # 6. kind_of? is an alias.\n      def k(v)\n        v.kind_of?(String) ? v.length : -1\n      end\n      p k(\"hello\")                #=> 5\n      p k(42)                     #=> -1\n\n      # 7. Soundness: a write inside the branch disables narrowing (no miscompile).\n      def wr(v)\n        if v.is_a?(Array)\n          v = v.to_a\n          v.length\n        else\n          0\n        end\n      end\n      p wr([1, 2, 3])             #=> 3\n\n      puts \"done\"\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [1, 2]\n      \"x\"\n      \"7\"\n      \"HI\"\n      [2, 4]\n      \"9\"\n      \"[\\\"ab\\\",\\\"cd\\\"]\"\n      50\n      \"q\"\n      3.5\n      \"z\"\n      \"a\"\n      1.5\n      5\n      -1\n      3\n      done\n    OUT\n  end\n\n  it \"issue 3327 strbuf push typed array\" do\n    result = ze0(<<~'RUBY')\n      class Res\n        attr_accessor :cookies\n        def initialize\n          @cookies = [\"\"]\n          @cookies.pop\n        end\n\n        def store(name, value)\n          line = name + \"=\" + value\n          line << \"; HttpOnly\"\n          @cookies.push(line)\n        end\n\n        def set_cookie(name, value)\n          line = name + \"=\" + value\n          line << \"; Path=/\"\n          @cookies.push(line)\n        end\n\n        def apply_cookie(name, value)\n          line = name + \"=\" + value\n          line << \"; Secure\"\n          @cookies.push(line)\n        end\n      end\n\n      res = Res.new\n      res.store(\"flash\", \"hello\")\n      res.set_cookie(\"sid\", \"42\")\n      res.apply_cookie(\"theme\", \"dark\")\n      res.cookies.each { |line| puts \"Set-Cookie: \" + line }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      Set-Cookie: flash=hello; HttpOnly\n      Set-Cookie: sid=42; Path=/\n      Set-Cookie: theme=dark; Secure\n    OUT\n  end\n\n  it \"issue 3330 unresolved at typed slots\" do\n    _(ze0(<<~'RUBY', path: \"compiler/fusion/issue_3330_unresolved_at_typed_slots.rb\")).must_answer \"\", stderr: \"compiler/fusion/issue_3330_unresolved_at_typed_slots.rb:5:in '<module:Sock>': uninitialized constant Sock::FFI (NameError)\\n\\n  extend FFI\\n         ^^^\\n\\tfrom compiler/fusion/issue_3330_unresolved_at_typed_slots.rb:4:in '<main>'\\n\", status: 1\n      # `include`/`extend`/`prepend` are ordinary method calls, so an unresolved\n      # target is a RUNTIME NameError raised from the class body -- on the directive's\n      # own line, with the enclosing bodies below it -- not a compile-time rejection.\n      module Sock\n        extend FFI\n        ffi_lib \"c\"\n        attach_function :puts_c, :puts, [:str], :int\n      end\n\n      class Boot\n        def start\n          if Missing::CONF.cert.length > 0\n            Sock.puts_c(Missing::CONF.cert)\n          end\n          deadline = Time.now.to_i + timeout_seconds\n          deadline\n        end\n      end\n\n      puts \"ok\"\n    RUBY\n  end\n\n  it \"ivar int table narrowing\" do\n    result = ze0(<<~'RUBY')\n      # An @ivar holding a table of int arrays gets the typed nested representation\n      # (an sp_PtrArray of sp_IntArray*), but only when EVERY reference to it is an\n      # op the narrowing models, from the owning class itself. An ivar's references\n      # span the whole class and escape through readers, returns and arguments, and a\n      # missed one is not a lost optimization -- it is an sp_PtrArray * meeting\n      # sp_RbVal in the emitted C. Each class below is one way out; only the last\n      # modeled one may narrow, and all of them must answer as CRuby does.\n      class A1\n        attr_reader :t\n        def initialize(n) = @t = Array.new(n) { 