# built landed in an sp_PtrArray * field and the emulator core-dumped.\n      class A8\n        def initialize\n          @m = [[1, 2], [3, 4]]\n        end\n        def go\n          @m[0][1] = @m[0][1] + 10\n          @m[0][1] + @m[1][0] + @m.length\n        end\n      end\n      p A8.new.go\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [2, 2]\n      2\n      3\n      9\n      0\n      10\n      \"a\"\n      17\n    OUT\n  end\n\n  it \"ivar orwrite raiseall typed slot\" do\n    result = ze0(<<~'RUBY')\n      # `@x ||= recv.map { ... }` where recv is typed poly/unknown produces a\n      # raise-all (sp_RbVal) RHS, but @x's slot was typed concretely (an array)\n      # from another assignment. The pointer-backed ivar or-write must keep the\n      # raise for effect and yield the slot's typed NULL so the C compiles, then\n      # raise NoMethodError at run time like CRuby (#2457, Family 1).\n      class Store\n        def taggings; @data; end\n        def seed(d); @memo = d; end\n        def compute\n          @memo ||= taggings.reject { |x| false }.map { |x| x }\n        end\n      end\n      s = Store.new\n      begin\n        p s.compute\n      rescue NoMethodError => e\n        p e.class\n      end\n      s2 = Store.new\n      s2.seed([10, 20])\n      p s2.compute\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      NoMethodError\n      [10, 20]\n    OUT\n  end\n\n  it \"keywords refused message\" do\n    result = ze0(<<~'RUBY')\n      # `**nil` in a signature declares that the method takes NO keywords. Passing\n      # some is `ArgumentError: no keywords accepted`; zeo reports an arity error\n      # instead, having folded the keywords into a trailing positional Hash.\n      #\n      # The distinction is the point of the syntax (ruby 3.0): before it, a method\n      # with no keyword parameters silently accepted `f(1, b: 2)` as a Hash argument,\n      # and `**nil` is how you say that the old behaviour is not wanted. zeo's message\n      # -- \"wrong