r the C library\n      # leaves behind. It was a divergence until zeo sorted through the same\n      # `qsort_r` CRuby's `ruby_qsort` calls. That makes the line PER PLATFORM, so\n      # there are two goldens: `.expected` is macOS, `.linux.expected` linux.\n      #\n      # The SECOND line is what the file was imported for:\n      #\n      # A local bound from a container read (`pair_a = pairs[a]`, where `pairs` is a\n      # table of int arrays) is narrowed to the element type. That decision and the\n      # pointer-array narrowing shared one pin field: the array pass put every pinned\n      # slot back on the poly array on the way in, the element pass narrowed it again,\n      # and the two traded the slot every round -- so the fixpoint never converged and\n      # every compile ran its whole round budget, leaving whatever types the cap\n      # happened to catch. (The LangArena program of #3781 compiled in 15s and lost\n      # an unrelated method's element type that way; it now settles in 1.3s.)\n      #\n      # Imported from the spinel corpus at c55d9bdb; see tests/spinel/UPSTREAM.md.\n\n      def sort_pairs(n)\n        rank = Array.new(n) { |i| (n - i) % 3 }\n        pairs = Array.new(n) { |i| [rank[i], rank[(i + 1) % n]] }\n        sa = Array.new(n) { |i| i }\n\n        sa.sort! do |a, b|\n          pair_a = pairs[a]\n          pair_b = pairs[b]\n          if pair_a[0] != pair_b[0]\n            pair_a[0] <=> pair_b[0]\n          else\n            pair_a[1] <=> pair_b[1]\n          end\n        end\n\n        ranks = Array.new(n, 0)\n        i = 1\n        while i < n\n          prev_pair = pairs[sa[i - 1]]\n          curr_pair = pairs[sa[i]]\n          ranks[sa[i]] = ranks[sa[i - 1]] + (prev_pair != curr_pair ? 1 : 0)\n          i += 1\n        end\n        [sa, ranks]\n      end\n\n      p sort_pairs(8)\n      p sort_pairs(3)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [[2, 5, 4, 1, 7, 3, 6, 0], [3, 1, 0, 3, 1, 0, 3, 2]]\n      [[0, 2, 1], [0, 2, 1]]\n    OUT\n  end\n\n  it \"nested array element narrows\" do\n    result = ze0(<<~'RUBY')\n      # an element read off a nested array narrows past the first level\n      rows = [[2026, 5, 1]]\n      m = rows[0][1]\n      p (1...m).reduce(0) { |s, i| s + i }\n      p (1..m).inject(0) { |s, i| s + i }\n      p (1...m).reverse_each.to_a\n      p (1...m).sum\n      p (1...m).to_a\n      strs = [[\"a\", \"b\"]]\n      sv = strs[0][1]\n      p sv.upcase\n      fl = [[1.5, 2.5]]\n      fv = fl[0][1]\n      p fv + 1\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      10\n      15\n      [4, 3, 2, 1]\n      10\n      [1, 2, 3, 4]\n      \"B\"\n      3.5\n    OUT\n  end\n\n  it \"nil typed equality\" do\n    result = ze0(<<~'RUBY')\n      # Two operands whose STATIC type is nil (calls the analyzer proves return\n      # nil) compare like literal nils: nil == nil is true, != is false, and both\n      # expressions still evaluate for their effects (the counter increments).\n      $calls = 0\n      def probe(x)\n        $calls += 1\n        nil\n      end\n\n      p probe(1) == probe(2)\n      p probe(3) != probe(4)\n      # One operand a literal nil: the non-literal side must still evaluate.\n      p probe(5) == nil\n      p nil == probe(6)\n      p $calls\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      true\n      false\n      true\n      true\n      6\n    OUT\n  end\n\n  it \"numbered params work through the times inline path\" do\n    result = ze0(<<~'RUBY')\n      3.times { puts _1 * 10 }\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      0\n      10\n      20\n    OUT\n  end\n\n  it \"param narrow from body call\" do\n    result = ze0(<<~'RUBY')\n      # Stage 1 of body-side type narrowing (B' direction): if a method's\n      # parameter is referenced in the body via `param.<m>` where `<m>` is\n      # defined on exactly one user class (and isn't a common operator /\n      # built-in-overlap method like `length`/`each`/`+`/...), the param's\n      # default `int` type narrows to `obj_<C>`.\n      #\n      # Without this narrowing the param stayed at `int` until a call-site\n      # arg-type widened it. For methods that are only ever called via a\n      # poly receiver (e.g. through `obj.method(:m)` or a heterogeneous\n      # poly_array dispatch), no concrete call site exists \xE2\x80\x94 caller-side\n      # widening can't fire \xE2\x80\x94 and the body would emit raw int operations\n      # against the param's expected user-class type.\n\n      class CPU\n        def peek_a(addr); addr * 2 + 1; end\n        def cycles_advance(n); n + 100; end\n      end\n\n      # Two separate methods that each take a CPU param. Neither has a\n      # direct call-site arg whose type spinel statically knows to be CPU\n      # at the time scan_new_calls runs (caller-side widening), so the\n      # narrow has to come from the body's method-call shapes.\n\n      def fetch(cpu, addr)\n        cpu.peek_a(addr)        # peek_a is only on CPU \xE2\x86\x92 narrow cpu to obj_CPU\n      end\n\n      def step(cpu, n)\n        cpu.cycles_advance(n)   # cycles_advance only on CPU \xE2\x86\x92 narrow\n      end\n\n      c = CPU.new\n      puts fetch(c, 7)          # 15\n      puts step(c, 3)           # 103\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      15\n      103\n    OUT\n  end\n\n  it \"pattern rest from typed array\" do\n    result = ze0(<<~'RUBY')\n      # A pattern's `*rest` bound from a poly scrutinee that holds a typed array.\n      def m(v)\n        case v\n        in [f, *r] then \"\#{f} +\#{r.inspect}\"\n        in Integer then \"int\"\n        end\n      end\n      puts m([1, 2, 3])\n      puts m([1.5, 2.5])\n      puts m(%w[a b c])\n      puts m([1, \"a\", nil])\n      puts m(7)\n\n      def tail(v)\n        case v\n        in [*init, last] then \"\#{init.inspect} \#{last}\"\n        in Integer then \"int\"\n        end\n      end\n      puts tail([1, 2, 3])\n      puts tail(%w[x y])\n\n      def mid(v)\n        case v\n        in [a, *m, z] then \"\#{a} \#{m.inspect} \#{z}\"\n        in Integer then \"int\"\n        end\n      end\n      puts mid([1, 2, 3, 4])\n      puts mid([1.0, 2.0])\n\n      def find(v)\n        case v\n        in [*pre, 3, *post] then \"\#{pre.inspect} | \#{post.inspect}\"\n        in Integer then \"int\"\n        end\n      end\n      puts find([1, 2, 3, 4, 5])\n      puts find([3])\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      1 +[2, 3]\n      1.5 +[2.5]\n      a +[\"b\", \"c\"]\n      1 +[\"a\", nil]\n      int\n      [1, 2] 3\n      [\"x\"] y\n      1 [2, 3] 4\n      1.0 [] 2.0\n      [1, 2] | [4, 5]\n      [] | []\n    OUT\n  end\n\n  it \"raise before a fused loop reaches the landing\" do\n    result = ze0(<<~'RUBY', env: {\"ZEO_RT_LEAKCHECK\" => \"1\"})\n\n      # The landing block is shared: `Fx::new` creates ONE of it and every\n      # `Fx::fallible` branches there, so a raise anywhere in a method reaches the\n      # same epilogue that a normal return does -- and that epilogue releases every\n      # slot in `fx.locals` unconditionally.\n      #\n      # A fused `n.times` splice takes no run-time guard, so it used to look safe.\n      # It was not: its block parameter's slot was nil-initialised where the splice\n      # was emitted, and a raise BEFORE the loop reached the landing without ever\n      # running that block. This pins the path.\n      #\n      # Runs under `ZEO_RT_LEAKCHECK=1`; the printed output is the same either way.\n      #\n      # HONEST LIMIT: this golden does NOT reproduce the bug on the pre-fix\n      # emitter -- it was tried, and it came out clean. The released bytes are\n      # stack garbage, and a short frame leaves benign garbage behind. What this\n      # file adds is coverage of the path, so a LOUD failure on it is caught.\n\n      def raises_before_a_loop(obj)\n        obj.no_such_method\n        3.times { |i| p i }\n      rescue NoMethodError => e\n        e.class\n      end\n\n      def raises_before_a_range_loop(obj)\n        obj.no_such_method\n        (0...3).each { |i| p i }\n      rescue NoMethodError => e\n        e.class\n      end\n\n      p raises_before_a_loop(Object.new)\n      p raises_before_a_range_loop(Object.new)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      NoMethodError\n      NoMethodError\n    OUT\n  end\n\n  it \"raise unless isa narrow\" do\n    result = ze0(<<~'RUBY')\n      # #493. `raise ... unless x.is_a?(C)` (and the equivalent\n      # `if !x.is_a?(C); raise ...; end` shape) is a definite-throw\n      # type assertion: when control reaches the statement after the\n      # guard, `x` is provably of class `C`. The repro from the issue:\n      #\n      #   def process(x)\n      #     raise TypeError, \"expected A\" unless x.is_a?(A)\n      #     puts x.body\n      #   end\n      #\n      # pre-fix emitted a full cls_id-switch over every class with a\n      # same-named field after the guard (sp_box_int for B#body's int,\n      # sp_box_str for A#body's string, then sp_poly_puts on the boxed\n      # result). post-fix the guard's narrow flows through to a single\n      # cls_id arm and the field read lowers to a direct\n      # `((sp_A *)lv_x.v.p)->iv_body` chain.\n      #\n      # Implementation: the analyze-side body walkers\n      # (scan_new_calls / collect_return_types_nid /\n      # scan_cls_method_calls) plus the codegen-side compile_body_return\n      # now push a sibling-scope type narrow when a stmt's\n      # parse_raise_guard_narrow recognizes the shape; the narrow stays\n      # pushed for the remainder of the StatementsNode. infer_type at\n      # codegen consults the narrow stack before honouring the\n      # pre-narrow @nd_inferred_type cache for `LV(narrowed).attr_reader`\n      # call shapes, so attr_reader resolution returns the narrowed\n      # class's static ivar type rather than the wider pre-narrow poly.\n\n      class A\n        attr_accessor :body\n        def initialize; @body = \"from-A\"; end\n      end\n\n      class B\n        attr_accessor :body\n        def initialize; @body = 42; end\n      end\n\n      def pick(n)\n        n > 0 ? A.new : B.new\n      end\n\n      def process_unless(x)\n        raise \"expected A\" unless x.is_a?(A)\n        puts x.body\n      end\n\n      def process_if_negated(x)\n        if !x.is_a?(A)\n          raise \"expected A\"\n        end\n        puts x.body\n      end\n\n      # Both spellings should resolve identically -- single A#body\n      # dispatch, no boxing through sp_RbVal.\n      process_unless(pick(1))\n      process_if_negated(pick(1))\n\n      # Multiple guards in sequence accumulate narrows.\n      class S\n        attr_accessor :name\n        def initialize; @name = \"sized\"; end\n      end\n\n      def render(s, t)\n        raise \"expected S\" unless s.is_a?(S)\n        raise \"expected S\" unless t.is_a?(S)\n        puts s.name + \"/\" + t.name\n      end\n\n      render(S.new, S.new)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      from-A\n      from-A\n      sized/sized\n    OUT\n  end\n\n  it \"random is seeded reproducible and typed\" do\n    result = ze0(<<~'RUBY')\n      p(Random.new(42).rand(1000) == Random.new(42).rand(1000))\n      p(Random.new(1).rand(1000) != Random.new(2).rand(1000))\n      p Random.new(5).rand(10).class\n      p Random.new(5).rand(2.5).class\n      p Random.new(5).rand.class\n      p((r = Random.new(9).rand(6)) >= 0 && r < 6)\n      p Random.new(1).bytes(8).bytesize\n      p Random.new(123).seed\n      p Random.new(3.9).seed\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      true\n      true\n      Integer\n      Float\n      Float\n      true\n      8\n      123\n      3\n    OUT\n  end\n\n  it \"range predicate typed argument\" do\n    result = ze0(<<~'RUBY')\n      b = \"x\"\n      p((1..5).cover?(b))\n      def g; \"x\"; end\n      p((1..5).cover?(g))\n      b = [1]; p((1..5).cover?(b))\n      b = { a: 1 }; p((1..5).include?(b))\n      b = :sym; p((1..5).member?(b))\n      b = nil;  p((1..5) === b)\n      b = 3;    p((1..5).cover?(b))\n      b = 2.5;  p((1..5).cover?(b))\n\n      # a Range operand: cover? is containment, === and include? are not\n      p((1..5).cover?(1...6))\n      p((1..5).cover?(2..9))\n      p((1..5).cover?(1.0..5.0))\n      p((1..5).cover?(1.0...5.5))\n      p((1...5).cover?(1..4))\n      p((1..5) === (1.0..5.0))\n      p((1..5).include?(1..2))\n      r = ((1..5).eql?(1.0..5.0) rescue $!.class); p r\n      fr = (1.0..5.0); r = ((1..5).eql?(fr) rescue $!.class); p r\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      false\n      false\n      false\n      false\n      false\n      false\n      true\n      true\n      true\n      false\n      true\n      false\n      true\n      false\n      false\n      false\n      false\n    OUT\n  end\n\n  it \"redefinition reaches a typed direct call site\" do\n    result = ze0(<<~'RUBY')\n      class Other\n        def unrelated = 0\n      end\n\n      class N\n        def initialize(v)\n          @v = v\n        end\n        attr_reader :v\n        def step(a) = @v + a\n      end\n\n      n = N.new(10)\n      puts n.step(1)\n      puts n.v\n\n      Other.define_method(:unrelated) { 1 }\n      puts n.step(2)\n      puts n.v\n\n      N.define_method(:step) { |a| @v * a }\n      puts n.step(3)\n\n      N.attr_accessor :v\n      n.v = 99\n      puts n.v\n      puts n.step(1)\n\n      o = N.new(5)\n      def o.step(a) = -a\n      puts o.step(4)\n      puts n.step(4)\n\n      module Doubler\n        def step(a) = 1000 + a\n      end\n      N.prepend(Doubler)\n      puts n.step(5)\n      puts N.new(1).step(6)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      11\n      10\n      12\n      10\n      30\n      99\n      99\n      -4\n      396\n      1005\n      1006\n    OUT\n  end\n\n  it \"require under a statically false engine guard is pruned not spliced\" do\n    _(ze0(<<~'RUBY')).must_answer \"ok\\n\"\n      # `require X if RUBY_ENGINE == \"jruby\"` names another e