lse\n\n      def starts?(s, pre)\n        return false unless pre.is_a?(String)\n        s.start_with?(pre)\n      end\n      p starts?(\"hello\", \"he\")   # true\n      p starts?(\"hello\", nil)    # false\n\n      def ends?(s, suf)\n        return false unless suf.is_a?(String)\n        s.end_with?(suf)\n      end\n      p ends?(\"hello\", \"lo\")     # true\n      p ends?(\"hello\", nil)      # false\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      true\n      false\n      true\n      false\n      true\n      false\n    OUT\n  end\n\n  it \"regexp inline comment\" do\n    result = ze0(<<~'RUBY')\n      # (?#comment) groups parse as empty atoms.\n      p(/foo(?#comment)bar/.match(\"foobar\") ? \"m\" : \"n\")\n      p(/foo(?#)bar/ =~ \"xfoobar\")\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      \"m\"\n      1\n    OUT\n  end\n\n  it \"unresolved value typed slot\" do\n    result = ze0(<<~'RUBY')\n      # An unresolved name lowers to a raising token whose C value is boxed. Landing\n      # it in a concretely-typed slot needs the coercing emit, or the emitted C\n      # assigns an sp_RbVal to the slot's own type and the program does not build at\n      # all. Two slots the coercion was not reaching: a `const char *` operand of a\n      # string concat (the token arrived wrapped in a paren, so the match missed it)\n      # and an object-pointer ivar written through an attr writer.\n      class Frame\n        attr_reader :n\n        def initialize(n); @n = n; end\n      end\n\n      class Holder\n        attr_accessor :frame\n        def initialize; @frame = Frame.new(1); end\n      end\n\n      # concat: the unresolved call is the right operand of `+`, written with the\n      # parentheses that hid the raising token from the coercion's text match\n      def concat_unresolved(a, b)\n        \"\" + (Missing.build(a.to_f, b.to_i))\n      end\n\n      begin\n        puts concat_unresolved(\"1.5\", \"2\")\n      rescue NameError => e\n        p e.class\n      end\n\n      def concat_unresolved_bare(a)\n        \"\" + Absent.build(a.to_i)\n      end\n\n      begin\n        puts concat_unresolved_bare(\"3\")\n      rescue NameError => e\n        p e.class\n      end\n\n      # object-pointer slot: an attr writer taking an unresolved name\n      h = Holder.new\n      p h.frame.n\n      begin\n        h.frame = missing_frame\n      rescue NameError => e\n        p e.class\n      end\n      p h.frame.n\n\n      # a resolvable value still goes into the same slot unchanged\n      h.frame = Frame.new(7)\n      p h.frame.n\n      p (\"\" + \"ok\")\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      NameError\n      NameError\n      1\n      NameError\n      1\n      7\n      \"ok\"\n    OUT\n  end\nend\n", "../../spec/compiler/guards/dispatch_test.rb" => "# frozen_string_literal: true\n\nrequire \"spec_helper\"\n\ndescribe \"Guards: dispatch\" do\n  it \"case guard defines a nested conditional class\" do\n    result = ze0(<<~'RUBY')\n      module Host\n      end\n      def engine = \"native\"\n      case engine\n      when \"java\"\n        module Host\n          class Backend\n            def id = \"j\"\n          end\n        end\n      else\n        module Host\n          class Backend\n            def id = \"n\"\n          end\n        end\n      end\n      puts Host.constants.sort.inspect\n      puts Host::Backend.new.id\n      puts defined?(Host::Backend)\n      h = Host::Backend\n      puts h.instance_method(:id).owner\n      puts h.new.respond_to?(:id)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      [:Backend]\n      n\n      constant\n      Host::Backend\n      true\n    OUT\n  end\n\n  it \"case in guard and class precedence\" do\n    result = ze0(<<~'RUBY')\n      class Classifier\n        def classify(v)\n          case v\n          in Integer => n if n % 2 == 0\n            \"even int \#{n}\"\n          in Integer\n            \"odd int\"\n          in String\n            \"string\"\n          else\n            \"other\"\n          end\n        end\n      end\n      c = Classifier.new\n      puts c.classify(4)\n      puts c.classify(3)\n      puts c.classify(\"hi\")\n      puts c.classify(nil)\n    RUBY\n\n    _(result).must_answer <<~'OUT'\n      even int 4\n      odd int\n      string\n      other\n    OUT\n  end\n\n  it \"class body guard asks about the class\" do\n    result = ze0(<<~'RUBY', files: {\"a_class_body_guard_asks_about_the_class/ext.rb\" => \"# Each reopen's body is ONE statement, which is the shape that used to break:\\n# the guard was lifted out of the class-body function and asked of `Gm`.\\nmodule Gm\\n  require_relative \\\"plat\\\"\\n\\n  class Plat\\n    unless respond_to?(:generic)\\n      WIDTH = 2\\n    end\\n  end\\n\\n  class Plat\\n    if respond_to?(:generic)\\n      HEIGHT = 3\\n    end\\n  end\\n\\n  class Plat\\n    unless const_defined?(:WIDTH)\\n      DEPTH = 4\\n    end\\n  end\\nend\\n\", \"a_class_body_guard_asks_about_the_class/plat.rb\" => \"# The half a later reopen probes: a singleton method and a constant, both\\n# already installed by the time the reopen's guard runs.\\nmodule Gm\\n  class Plat\\n    WIDTH = 1\\n\\n    class << self\\n      def generic(name) = name\\n    end\\n  end\\nend\\n\"})\n      # A guard the SOURCE wrote inside a class body asks about the CLASS, and runs\n      # where it is written -- inside the class-body frame, with `self` bound to the\n      # class.\n      #\n      # Zeo lifts a class body's sole `if` statement back out into the enclosing\n      # scope, because analyze SYNTHESIZES exactly that shape when it pushes a\n      # `class X ... end if cond` guard into the body: there the condition was\n      # written outside, and its locals live outside. A guard the source wrote\n      # inside the body is indistinguishable by shape, so it was lifted too -- and\n      # then `self` was the enclosing module rather than the class, so every\n      # `respond_to?` / `const_defined?` probe asked about the