      # at runtime through its compiled-in unit.
      require_relative "conditional_require_units/loud" if ENV["ZEO_TEST_NEVER_SET"]
      puts "between"
      require_relative "conditional_require_units/second" if ENV["HOME"]
      puts "after"
    RUBY

    _(result).must_answer <<~'OUT'
      between
      second loaded
      after
    OUT
  end

